import React from 'react';
import ReactDOM from 'react-dom/client';
import App from './App';

const rootElement = document.getElementById('root');
if (!rootElement) {
  throw new Error("Could not find root element to mount to");
}

const root = ReactDOM.createRoot(rootElement);
root.render(
  <React.StrictMode>
    <App />
  </React.StrictMode>
);

export interface NewsItem {
  id: string;
  title: string;
  summary: string;
  category: string;
  relevance: number;
}

export interface GroundingSource {
  title: string;
  uri: string;
}

export interface NewsState {
  items: NewsItem[];
  sources: GroundingSource[];
  loading: boolean;
  error: string | null;
  lastUpdated: string | null;
}

export type Category = 'General' | 'AI' | 'Startups' | 'Hardware' | 'Software' | 'Cybersecurity';

import { GoogleGenAI, Type } from "@google/genai";
import { NewsItem, GroundingSource } from "../types";

const ai = new GoogleGenAI({ apiKey: process.env.API_KEY || '' });

export const fetchTechNews = async (category: string = 'General'): Promise<{ items: NewsItem[], sources: GroundingSource[] }> => {
  const yesterday = new Date();
  yesterday.setDate(yesterday.getDate() - 1);
  const dateString = yesterday.toLocaleDateString('en-US', { year: 'numeric', month: 'long', day: 'numeric' });

  const prompt = `Provide a comprehensive summary of the most important technology news from yesterday (${dateString}). 
  Category focus: ${category}.
  Structure the response as a JSON array of objects. Each object MUST have:
  - id: a unique string
  - title: clear headline
  - summary: 2-3 sentences explaining the news and its impact
  - category: one of [AI, Startups, Hardware, Software, Cybersecurity]
  - relevance: integer 1-10 (how critical this news is)`;

  try {
    const response = await ai.models.generateContent({
      model: "gemini-3-flash-preview",
      contents: prompt,
      config: {
        tools: [{ googleSearch: {} }],
        responseMimeType: "application/json",
        responseSchema: {
          type: Type.ARRAY,
          items: {
            type: Type.OBJECT,
            properties: {
              id: { type: Type.STRING },
              title: { type: Type.STRING },
              summary: { type: Type.STRING },
              category: { type: Type.STRING },
              relevance: { type: Type.INTEGER }
            },
            required: ["id", "title", "summary", "category", "relevance"]
          }
        }
      },
    });

    const items: NewsItem[] = JSON.parse(response.text);

    // Extract grounding sources
    const sources: GroundingSource[] = [];
    const chunks = response.candidates?.[0]?.groundingMetadata?.groundingChunks;

    if (chunks) {
      chunks.forEach((chunk: any) => {
        if (chunk.web && chunk.web.uri && chunk.web.title) {
          sources.push({
            title: chunk.web.title,
            uri: chunk.web.uri
          });
        }
      });
    }

    // Deduplicate sources
    const uniqueSources = Array.from(new Map(sources.map(s => [s.uri, s])).values());

    return { items, sources: uniqueSources };
  } catch (error) {
    console.error("Gemini API Error:", error);
    throw new Error("Failed to fetch latest tech news. Please check your API key and network connection.");
  }
};

