              <span className="text-xs text-slate-500 mono">Synced: {state.lastUpdated}</span>
            )}
          </div>
          <p className="text-slate-400">
            High-fidelity summary of global tech developments filtered for <span className="text-blue-400 font-semibold">{activeCategory}</span>.
          </p>
        </header>

        {state.error && (
          <div className="bg-rose-500/10 border border-rose-500/30 p-4 rounded-xl text-rose-400 flex items-center gap-3 mb-8">
            <svg className="w-5 h-5 flex-shrink-0" fill="none" stroke="currentColor" viewBox="0 0 24 24"><path strokeLinecap="round" strokeLinejoin="round" strokeWidth="2" d="M12 8v4m0 4h.01M21 12a9 9 0 11-18 0 9 9 0 0118 0z"></path></svg>
            <p className="text-sm">{state.error}</p>
            <button 
              onClick={() => loadNews(activeCategory)}
              className="ml-auto underline font-bold"
            >
              Retry
            </button>
          </div>
        )}

        {state.loading ? (
          <div className="grid grid-cols-1 md:grid-cols-2 lg:grid-cols-3 gap-6">
            {[1, 2, 3, 4, 5, 6].map((i) => (
              <div key={i} className="glass rounded-2xl p-6 animate-pulse h-64">
                <div className="h-4 w-1/4 bg-white/5 rounded mb-6"></div>
                <div className="h-6 w-3/4 bg-white/10 rounded mb-4"></div>
                <div className="h-4 w-full bg-white/5 rounded mb-2"></div>
                <div className="h-4 w-full bg-white/5 rounded mb-2"></div>
                <div className="h-4 w-2/3 bg-white/5 rounded mt-auto"></div>
              </div>
            ))}
          </div>
        ) : (
          <>
            <div className="grid grid-cols-1 md:grid-cols-2 lg:grid-cols-3 gap-6">
              {state.items.map((item) => (
                <NewsCard key={item.id} item={item} />
              ))}
            </div>
            <SourceList sources={state.sources} />
          </>
        )}

        {!state.loading && state.items.length === 0 && !state.error && (
          <div className="text-center py-24 glass rounded-3xl">
            <div className="bg-slate-800 w-16 h-16 rounded-full flex items-center justify-center mx-auto mb-4">
              <svg className="w-8 h-8 text-slate-500" fill="none" stroke="currentColor" viewBox="0 0 24 24"><path strokeLinecap="round" strokeLinejoin="round" strokeWidth="2" d="M12 8v4l3 3m6-3a9 9 0 11-18 0 9 9 0 0118 0z"></path></svg>
            </div>
            <h3 className="text-xl font-bold text-white">No news found</h3>
            <p className="text-slate-400">Try switching categories or checking back later.</p>
          </div>
        )}
      </main>

