      <footer className="mt-20 py-10 border-t border-white/5">
        <div className="max-w-7xl mx-auto px-6 flex flex-col items-center text-center">
          <p className="text-slate-500 text-sm mb-4">
            Powered by Gemini 3 Flash and Google Search Grounding for real-time accuracy.
          </p>
          <div className="flex gap-4 text-xs text-slate-600 uppercase tracking-widest font-bold">
            <span className="hover:text-slate-400 cursor-pointer transition-colors">Twitter</span>
            <span className="hover:text-slate-400 cursor-pointer transition-colors">Discord</span>
            <span className="hover:text-slate-400 cursor-pointer transition-colors">API Docs</span>
          </div>
        </div>
      </footer>
    </div>
  );
};

export default App;

