export const fetchDeepAnalysis = async (item: NewsItem): Promise<AnalysisData> => {
  const prompt = `Analyze this specific tech news item in depth: "${item.title}". 
  Context: ${item.summary}

  Provide a structured analysis covering:
  1. Market Impact: How does this affect competitors and the industry?
  2. Technical Context: What underlying technology is at play?
  3. Future Outlook: What should we expect in the next 6 months?

  Return ONLY a JSON object with keys: marketImpact, technicalContext, futureOutlook.`;

  try {
    const response = await ai.models.generateContent({
      model: "gemini-3-flash-preview",
      contents: prompt,
      config: {
        tools: [{ googleSearch: {} }],
        responseMimeType: "application/json",
        responseSchema: {
          type: Type.OBJECT,
          properties: {
            marketImpact: { type: Type.STRING },
            technicalContext: { type: Type.STRING },
            futureOutlook: { type: Type.STRING }
          },
          required: ["marketImpact", "technicalContext", "futureOutlook"]
        }
      },
    });

    const analysis = JSON.parse(response.text);
    const sources: GroundingSource[] = [];
    const chunks = response.candidates?.[0]?.groundingMetadata?.groundingChunks;

    if (chunks) {
      chunks.forEach((chunk: any) => {
        if (chunk.web && chunk.web.uri && chunk.web.title) {
          sources.push({ title: chunk.web.title, uri: chunk.web.uri });
        }
      });
    }

    return {
      ...analysis,
      sources: Array.from(new Map(sources.map(s => [s.uri, s])).values())
    };
  } catch (error) {
    console.error("Analysis Error:", error);
    throw new Error("Failed to perform deep analysis.");
  }
};

