import { GoogleGenAI, Type } from "@google/genai";
import { NewsItem, GroundingSource, AnalysisData } from "../types";

const ai = new GoogleGenAI({ apiKey: process.env.API_KEY || '' });

export const fetchTechNews = async (category: string = 'General'): Promise<{ items: NewsItem[], sources: GroundingSource[] }> => {
  const yesterday = new Date();
  yesterday.setDate(yesterday.getDate() - 1);
  const dateString = yesterday.toLocaleDateString('en-US', { year: 'numeric', month: 'long', day: 'numeric' });

  // Explicitly mentioning techmeme.com as a primary source for filtering high-signal news
  const prompt = `Provide a comprehensive summary of the most important technology news from yesterday (${dateString}). 
  You should prioritize news and discussions found on high-signal tech aggregators like techmeme.com, as well as major tech journalism outlets.

  Category focus: ${category}.

  Structure the response as a JSON array of objects. Each object MUST have:
  - id: a unique string
  - title: clear headline (similar to how Techmeme might present it)
  - summary: 2-3 sentences explaining the news and its impact
  - category: one of [AI, Startups, Hardware, Software, Cybersecurity]
  - relevance: integer 1-10 (how critical this news is)`;

  try {
    const response = await ai.models.generateContent({
      model: "gemini-3-flash-preview",
      contents: prompt,
      config: {
        tools: [{ googleSearch: {} }],
        responseMimeType: "application/json",
        responseSchema: {
          type: Type.ARRAY,
          items: {
            type: Type.OBJECT,
            properties: {
              id: { type: Type.STRING },
              title: { type: Type.STRING },
              summary: { type: Type.STRING },
              category: { type: Type.STRING },
              relevance: { type: Type.INTEGER }
            },
            required: ["id", "title", "summary", "category", "relevance"]
          }
        }
      },
    });

    const items: NewsItem[] = JSON.parse(response.text);

    // Extract grounding sources
    const sources: GroundingSource[] = [];
    const chunks = response.candidates?.[0]?.groundingMetadata?.groundingChunks;

    if (chunks) {
      chunks.forEach((chunk: any) => {
        if (chunk.web && chunk.web.uri && chunk.web.title) {
          sources.push({
            title: chunk.web.title,
            uri: chunk.web.uri
          });
        }
      });
    }

    const uniqueSources = Array.from(new Map(sources.map(s => [s.uri, s])).values());
    return { items, sources: uniqueSources };
  } catch (error) {
    console.error("Gemini API Error:", error);
    throw new Error("Failed to fetch latest tech news.");
  }
};

