import { GoogleGenAI, Type } from "@google/genai";
import { NewsItem, GroundingSource, AnalysisData } from "../types";

const ai = new GoogleGenAI({ apiKey: process.env.API_KEY || '' });

export const fetchTechNews = async (
  category: string = 'General', 
  preferredSources: string[] = []
): Promise<{ items: NewsItem[], sources: GroundingSource[] }> => {
  const now = new Date();
  const yesterday = new Date(now.getTime() - (24 * 60 * 60 * 1000));

  const dateStringNow = now.toLocaleDateString('en-US', { year: 'numeric', month: 'long', day: 'numeric', hour: '2-digit', minute: '2-digit' });
  const dateStringYesterday = yesterday.toLocaleDateString('en-US', { year: 'numeric', month: 'long', day: 'numeric', hour: '2-digit', minute: '2-digit' });

  const sourcesContext = preferredSources.length > 0 
    ? `EXCLUSIVELY or HEAVILY prioritize news from these specific domains: ${preferredSources.join(', ')}.`
    : `Prioritize news found on high-signal tech aggregators like techmeme.com and major tech journalism outlets.`;

  const prompt = `Provide a comprehensive list of EXACTLY 50 unique and critical technology news items from the LAST 24 HOURS (between ${dateStringYesterday} and ${dateStringNow}). 

  Source Preference: ${sourcesContext}

  Category focus: ${category}.

  Your goal is to act as a world-class tech curator. Provide a massive, high-fidelity daily digest. 
  Include major industry shifts, product launches, significant funding rounds, policy changes, and breaking technical releases.

  It is MANDATORY that you provide 50 distinct items. If the category is narrow, include secondary and tertiary news updates to reach the count of 50. 

  Structure the response as a JSON array of objects. Each object MUST have:
  - id: a unique string
  - title: clear, impactful headline
  - summary: 1-2 concise sentences explaining the news and why it matters
  - category: one of [AI, Startups, Hardware, Software, Cybersecurity]
  - relevance: integer 1-10 (how critical this story is to the industry)`;

  try {
    const response = await ai.models.generateContent({
      model: "gemini-3-flash-preview",
      contents: prompt,
      config: {
        tools: [{ googleSearch: {} }],
        responseMimeType: "application/json",
        responseSchema: {
          type: Type.ARRAY,
          items: {
            type: Type.OBJECT,
            properties: {
              id: { type: Type.STRING },
              title: { type: Type.STRING },
              summary: { type: Type.STRING },
              category: { type: Type.STRING },
              relevance: { type: Type.INTEGER }
            },
            required: ["id", "title", "summary", "category", "relevance"]
          }
        }
      },
    });

    const items: NewsItem[] = JSON.parse(response.text);

    const sources: GroundingSource[] = [];
    const chunks = response.candidates?.[0]?.groundingMetadata?.groundingChunks;

    if (chunks) {
      chunks.forEach((chunk: any) => {
        if (chunk.web && chunk.web.uri && chunk.web.title) {
          sources.push({
            title: chunk.web.title,
            uri: chunk.web.uri
          });
        }
      });
    }

    const uniqueSources = Array.from(new Map(sources.map(s => [s.uri, s])).values());
    return { items, sources: uniqueSources };
  } catch (error) {
    console.error("Gemini API Error:", error);
    throw new Error("Failed to fetch the 24h tech digest. Please try again in a moment.");
  }
};

