import React, { useState, useEffect, useCallback, useMemo } from 'react';
import { fetchTechNews, fetchDeepAnalysis } from './services/geminiService';
import { NewsItem, Category, NewsState, AnalysisData, SourceOption } from './types';
import NewsCard from './components/NewsCard';
import SourceList from './components/SourceList';
import AnalysisModal from './components/AnalysisModal';

const PRESET_SOURCES: SourceOption[] = [
  { id: 'techmeme', name: 'Techmeme', domain: 'techmeme.com' },
  { id: 'verge', name: 'The Verge', domain: 'theverge.com' },
  { id: 'tc', name: 'TechCrunch', domain: 'techcrunch.com' },
  { id: 'hn', name: 'Hacker News', domain: 'news.ycombinator.com' },
  { id: 'ars', name: 'Ars Technica', domain: 'arstechnica.com' },
];

const ITEMS_PER_PAGE = 6;

const App: React.FC = () => {
  const [hasAuth, setHasAuth] = useState<boolean | null>(null);
  const [state, setState] = useState<NewsState>({
    items: [],
    sources: [],
    loading: true,
    error: null,
    lastUpdated: null
  });
  const [activeCategory, setActiveCategory] = useState<Category>('General');
  const [selectedSourceIds, setSelectedSourceIds] = useState<string[]>(['techmeme']);
  const [currentPage, setCurrentPage] = useState(1);

  // Analysis specific state
  const [selectedItem, setSelectedItem] = useState<NewsItem | null>(null);
  const [analysisData, setAnalysisData] = useState<AnalysisData | null>(null);
  const [isAnalysisLoading, setIsAnalysisLoading] = useState(false);

  const categories: Category[] = ['General', 'AI', 'Startups', 'Hardware', 'Software', 'Cybersecurity'];

  // Authentication check
  useEffect(() => {
    const checkAuth = async () => {
      // @ts-ignore
      const authorized = await window.aistudio.hasSelectedApiKey();
      setHasAuth(authorized);
    };
    checkAuth();
  }, []);

  const handleAuthorize = async () => {
    // @ts-ignore
    await window.aistudio.openSelectKey();
    setHasAuth(true); // Proceed assuming success per race condition mitigation rules
  };

  // Sort and paginate data
  const sortedItems = useMemo(() => {
    return [...state.items].sort((a, b) => b.relevance - a.relevance);
  }, [state.items]);

  const totalPages = Math.ceil(sortedItems.length / ITEMS_PER_PAGE);

  const paginatedItems = useMemo(() => {
    const startIndex = (currentPage - 1) * ITEMS_PER_PAGE;
    return sortedItems.slice(startIndex, startIndex + ITEMS_PER_PAGE);
  }, [sortedItems, currentPage]);

  const toggleSource = (id: string) => {
    setSelectedSourceIds(prev => 
      prev.includes(id) ? prev.filter(s => s !== id) : [...prev, id]
    );
    setCurrentPage(1);
  };

  const handleCategoryChange = (cat: Category) => {
    setActiveCategory(cat);
    setCurrentPage(1);
  };

  const loadNews = useCallback(async (cat: string, sourceIds: string[]) => {
    if (hasAuth === false) return;

    setState(prev => ({ ...prev, loading: true, error: null }));
    const domains = PRESET_SOURCES
      .filter(s => sourceIds.includes(s.id))
      .map(s => s.domain);

    try {
      const data = await fetchTechNews(cat, domains);
      setState({
        items: data.items,
        sources: data.sources,
        loading: false,
        error: null,
        lastUpdated: new Date().toLocaleTimeString([], { hour: '2-digit', minute: '2-digit' })
      });
    } catch (err: any) {
      if (err.message === "AUTH_REQUIRED") {
        setHasAuth(false);
      } else {
        setState(prev => ({ 
          ...prev, 
          loading: false, 
          error: err.message || 'An unexpected error occurred' 
        }));
      }
    }
  }, [hasAuth]);

  const handleOpenAnalysis = async (item: NewsItem) => {
    setSelectedItem(item);
    setIsAnalysisLoading(true);
    setAnalysisData(null);

    try {
      const analysis = await fetchDeepAnalysis(item);
      setAnalysisData(analysis);
    } catch (err: any) {
      if (err.message === "AUTH_REQUIRED") {
        setHasAuth(false);
        setSelectedItem(null);
      }
      console.error(err);
    } finally {
      setIsAnalysisLoading(false);
    }
  };

  const handleCloseAnalysis = () => {
    setSelectedItem(null);
    setAnalysisData(null);
  };

  useEffect(() => {
    if (hasAuth === true) {
      loadNews(activeCategory, selectedSourceIds);
    }
  }, [activeCategory, selectedSourceIds, loadNews, hasAuth]);

  // Auth Landing Screen
  if (hasAuth === false) {
    return (
      <div className="min-h-screen flex items-center justify-center bg-[#0f172a] p-6">
        <div className="max-w-md w-full glass p-10 rounded-[2.5rem] border border-white/10 text-center shadow-2xl relative overflow-hidden">
          <div className="absolute top-0 left-0 w-full h-1 bg-gradient-to-r from-blue-500 via-purple-500 to-blue-500 animate-pulse" />

          <div className="w-20 h-20 bg-blue-600 rounded-2xl flex items-center justify-center mx-auto mb-8 shadow-lg shadow-blue-500/20 rotate-3">
            <span className="text-white font-black text-4xl">T</span>
          </div>

          <h1 className="text-3xl font-bold text-white mb-4 tracking-tight">Personal Terminal</h1>
          <p className="text-slate-400 mb-10 leading-relaxed text-sm">
            This instance of TechPulse is configured as a private tool. To access your personal 24h news digest, please authorize with your API key.
          </p>

          <button
            onClick={handleAuthorize}
            className="w-full bg-blue-600 hover:bg-blue-500 text-white font-bold py-4 rounded-2xl transition-all active:scale-[0.98] shadow-lg shadow-blue-600/20 flex items-center justify-center gap-3 mb-6"
          >
            <svg className="w-5 h-5" fill="none" stroke="currentColor" viewBox="0 0 24 24"><path strokeLinecap="round" strokeLinejoin="round" strokeWidth="2" d="M12 15v2m-6 4h12a2 2 0 002-2v-6a2 2 0 00-2-2H6a2 2 0 00-2 2v6a2 2 0 002 2zm10-10V7a4 4 0 00-8 0v4h8z"></path></svg>
            Authorize Private Instance
          </button>

          <a 
            href="https://ai.google.dev/gemini-api/docs/billing" 
            target="_blank" 
            rel="noreferrer"
            className="text-[10px] text-slate-500 uppercase tracking-widest font-black hover:text-blue-400 transition-colors"
          >
            View Billing Documentation
          </a>
        </div>
      </div>
    );
  }

  // Loading state for initial auth check
  if (hasAuth === null) {
    return (
      <div className="min-h-screen flex items-center justify-center">
        <div className="w-8 h-8 border-2 border-blue-500/20 border-t-blue-500 rounded-full animate-spin" />
      </div>
    );
  }

  return (
    <div className="min-h-screen pb-20">
      <AnalysisModal 
        item={selectedItem} 
        data={analysisData} 
        loading={isAnalysisLoading} 
        onClose={handleCloseAnalysis} 
      />

      <nav className="sticky top-0 z-50 glass border-b border-white/5 px-6 py-4 mb-8">
        <div className="max-w-7xl mx-auto flex flex-col md:flex-row md:items-center justify-between gap-4">
          <div className="flex items-center gap-2">
            <div className="w-8 h-8 bg-blue-600 rounded-lg flex items-center justify-center shadow-lg shadow-blue-500/20">
              <span className="text-white font-black text-lg">T</span>
            </div>
            <h1 className="text-xl font-bold tracking-tight bg-gradient-to-r from-white to-slate-400 bg-clip-text text-transparent">
              TechPulse
            </h1>
          </div>

          <div className="flex overflow-x-auto gap-2 no-scrollbar pb-1 md:pb-0">
            {categories.map((cat) => (
              <button
                key={cat}
                onClick={() => handleCategoryChange(cat)}
                className={`px-4 py-1.5 rounded-full text-sm font-medium transition-all whitespace-nowrap ${
                  activeCategory === cat
                    ? 'bg-blue-600 text-white'
                    : 'text-slate-400 hover:text-white hover:bg-white/5'
                }`}
              >
                {cat}
              </button>
            ))}
          </div>
        </div>
      </nav>

      <main className="max-w-7xl mx-auto px-6">
        <header className="mb-10">
          <div className="flex flex-col md:flex-row md:items-end justify-between gap-6 mb-6">
            <div>
              <div className="flex items-center gap-3 mb-2">
                <h2 className="text-3xl font-bold text-white tracking-tight">24h Tech Digest</h2>
                <div className="flex items-center gap-1.5 px-2 py-1 rounded-md bg-blue-500/10 border border-blue-500/20">
                  <span className="w-1.5 h-1.5 rounded-full bg-blue-500 animate-pulse" />
                  <span className="text-[10px] font-black text-blue-500 uppercase tracking-wider">Active Window</span>
                </div>
              </div>
              <p className="text-slate-400 max-w-2xl leading-relaxed">
                A high-fidelity synthesis of technology developments from the last 24 hours. Ranked by industry impact.
              </p>
            </div>

            {state.lastUpdated && !state.loading && (
              <div className="flex items-center gap-2 text-slate-500 mono text-xs bg-white/5 px-3 py-1.5 rounded-lg border border-white/5">
                <svg className="w-3 h-3" fill="none" stroke="currentColor" viewBox="0 0 24 24"><path strokeLinecap="round" strokeLinejoin="round" strokeWidth="2" d="M4 4v5h.582m15.356 2A8.001 8.001 0 004.582 9m0 0H9m11 11v-5h-.581m0 0a8.003 8.003 0 01-15.357-2m15.357 2H15"></path></svg>
                Sync Time: {state.lastUpdated}
              </div>
            )}
          </div>

          <div className="flex flex-col gap-3">
            <span className="text-[10px] font-bold text-slate-500 uppercase tracking-[0.2em]">Source Filter</span>
            <div className="flex flex-wrap gap-2">
              {PRESET_SOURCES.map((source) => (
                <button
                  key={source.id}
                  onClick={() => toggleSource(source.id)}
                  className={`flex items-center gap-2 px-3 py-1.5 rounded-lg border transition-all text-xs font-medium ${
                    selectedSourceIds.includes(source.id)
                      ? 'bg-blue-500/20 border-blue-500/50 text-blue-200 shadow-[0_0_15px_rgba(59,130,246,0.1)]'
                      : 'bg-white/5 border-white/10 text-slate-400 hover:text-slate-200 hover:border-white/20'
                  }`}
                >
                  <img 
                    src={`https://www.google.com/s2/favicons?domain=${source.domain}`} 
                    className={`w-3 h-3 rounded-sm grayscale transition-all ${selectedSourceIds.includes(source.id) ? 'grayscale-0' : ''}`}
                    alt="" 
                  />
                  {source.name}
                  {selectedSourceIds.includes(source.id) && (
                    <svg className="w-3 h-3 text-blue-400" fill="none" stroke="currentColor" viewBox="0 0 24 24"><path strokeLinecap="round" strokeLinejoin="round" strokeWidth="3" d="M5 13l4 4L19 7"></path></svg>
                  )}
                </button>
              ))}
              <button 
                onClick={() => { setSelectedSourceIds([]); setCurrentPage(1); }}
                className="px-3 py-1.5 rounded-lg border border-white/5 text-slate-500 text-xs hover:text-slate-300 transition-colors"
              >
                Clear All
              </button>
            </div>
          </div>
        </header>

        {state.error && (
          <div className="bg-rose-500/10 border border-rose-500/30 p-5 rounded-2xl text-rose-400 flex items-center gap-4 mb-8">
            <div className="w-10 h-10 rounded-full bg-rose-500/20 flex items-center justify-center flex-shrink-0">
              <svg className="w-5 h-5" fill="none" stroke="currentColor" viewBox="0 0 24 24"><path strokeLinecap="round" strokeLinejoin="round" strokeWidth="2" d="M12 9v2m0 4h.01m-6.938 4h13.856c1.54 0 2.502-1.667 1.732-3L13.732 4c-.77-1.333-2.694-1.333-3.464 0L3.34 16c-.77 1.333.192 3 1.732 3z"></path></svg>
            </div>
            <div>
              <p className="font-bold">Fetch Error</p>
              <p className="text-sm opacity-80">{state.error}</p>
            </div>
            <button 
              onClick={() => loadNews(activeCategory, selectedSourceIds)}
              className="ml-auto px-4 py-2 bg-rose-500/20 hover:bg-rose-500/30 rounded-lg text-sm font-bold transition-all"
            >
              Retry
            </button>
          </div>
        )}

        {state.loading ? (
          <div className="grid grid-cols-1 md:grid-cols-2 lg:grid-cols-3 gap-6">
            {[1, 2, 3, 4, 5, 6].map((i) => (
              <div key={i} className="glass rounded-2xl p-6 animate-pulse h-64 border border-white/5">
                <div className="h-4 w-1/4 bg-white/5 rounded mb-6"></div>
                <div className="h-6 w-3/4 bg-white/10 rounded mb-4"></div>
                <div className="h-4 w-full bg-white/5 rounded mb-2"></div>
                <div className="h-4 w-full bg-white/5 rounded mb-2"></div>
                <div className="h-4 w-2/3 bg-white/5 rounded mt-auto"></div>
              </div>
            ))}
          </div>
        ) : (
          <>
            <div className="grid grid-cols-1 md:grid-cols-2 lg:grid-cols-3 gap-6">
              {paginatedItems.map((item) => (
                <NewsCard key={item.id} item={item} onAnalyze={handleOpenAnalysis} />
              ))}
            </div>

            {totalPages > 1 && (
              <div className="mt-12 flex items-center justify-center gap-2">
                <button
                  onClick={() => setCurrentPage(p => Math.max(1, p - 1))}
                  disabled={currentPage === 1}
                  className="p-2 rounded-lg border border-white/10 text-slate-400 hover:text-white hover:bg-white/5 disabled:opacity-30 disabled:hover:bg-transparent transition-all"
                >
                  <svg className="w-5 h-5" fill="none" stroke="currentColor" viewBox="0 0 24 24"><path strokeLinecap="round" strokeLinejoin="round" strokeWidth="2" d="M15 19l-7-7 7-7"></path></svg>
                </button>

                <div className="flex items-center gap-1">
                  {Array.from({ length: totalPages }, (_, i) => i + 1).map(page => (
                    <button
                      key={page}
                      onClick={() => setCurrentPage(page)}
                      className={`w-10 h-10 rounded-lg border transition-all text-xs font-bold ${
                        currentPage === page
                          ? 'bg-blue-600 border-blue-500 text-white shadow-lg shadow-blue-500/20'
                          : 'border-white/10 text-slate-400 hover:text-white hover:bg-white/5'
                      }`}
                    >
                      {page}
                    </button>
                  ))}
                </div>

                <button
                  onClick={() => setCurrentPage(p => Math.min(totalPages, p + 1))}
                  disabled={currentPage === totalPages}
                  className="p-2 rounded-lg border border-white/10 text-slate-400 hover:text-white hover:bg-white/5 disabled:opacity-30 disabled:hover:bg-transparent transition-all"
                >
                  <svg className="w-5 h-5" fill="none" stroke="currentColor" viewBox="0 0 24 24"><path strokeLinecap="round" strokeLinejoin="round" strokeWidth="2" d="M9 5l7 7-7 7"></path></svg>
                </button>
              </div>
            )}

            <SourceList sources={state.sources} />
          </>
        )}

        {!state.loading && state.items.length === 0 && !state.error && (
          <div className="text-center py-24 glass rounded-3xl border border-dashed border-white/10">
            <div className="bg-slate-800/50 w-20 h-20 rounded-full flex items-center justify-center mx-auto mb-6 shadow-inner">
              <svg className="w-10 h-10 text-slate-500" fill="none" stroke="currentColor" viewBox="0 0 24 24"><path strokeLinecap="round" strokeLinejoin="round" strokeWidth="2" d="M19 20H5a2 2 0 01-2-2V6a2 2 0 012-2h10a2 2 0 012 2v1m2 13a2 2 0 01-2-2V7m2 13a2 2 0 002-2V9a2 2 0 00-2-2h-2m-4-3H9M7 16h6M7 8h6v4H7V8z"></path></svg>
            </div>
            <h3 className="text-2xl font-bold text-white mb-2">No 24h Data Found</h3>
            <p className="text-slate-400 max-w-md mx-auto">
              We couldn't find any news for {activeCategory} in the last 24 hours. Try broader settings.
            </p>
          </div>
        )}
      </main>

      <footer className="mt-20 py-12 border-t border-white/5 relative overflow-hidden">
        <div className="absolute top-0 left-1/2 -translate-x-1/2 w-1/2 h-px bg-gradient-to-r from-transparent via-blue-500/50 to-transparent" />
        <div className="max-w-7xl mx-auto px-6 flex flex-col items-center text-center">
          <div className="flex items-center gap-2 mb-6">
            <div className="w-6 h-6 bg-blue-600 rounded flex items-center justify-center">
              <span className="text-white font-black text-xs">T</span>
            </div>
            <span className="font-bold text-slate-300">TechPulse Intelligence (Private)</span>
          </div>
          <p className="text-slate-500 text-sm max-w-lg mb-8 leading-relaxed">
            Personal tech news synthesis from the last 24 hours.
          </p>
          <div className="flex gap-8 text-[10px] text-slate-500 uppercase tracking-[0.3em] font-black">
             <button onClick={handleAuthorize} className="hover:text-blue-400 transition-colors">Reset Auth</button>
             <span className="text-slate-700">|</span>
            <span className="hover:text-blue-400 cursor-pointer transition-colors">Newsletter</span>
            <span className="hover:text-blue-400 cursor-pointer transition-colors">Privacy</span>
          </div>
        </div>
      </footer>
    </div>
  );
};

export default App;

{
  "name": "My Daily Digest",
  "description": "Your personal, high-fidelity daily scan of the tech industry. Leveraging Gemini 3 to synthesize the last 24 hours into a prioritized digest.",
  "requestFramePermissions": []
}

import React, { useState, useEffect, useCallback, useMemo } from 'react';
import { fetchTechNews, fetchDeepAnalysis } from './services/geminiService';
import { NewsItem, Category, NewsState, AnalysisData, SourceOption } from './types';
import NewsCard from './components/NewsCard';
import SourceList from './components/SourceList';
import AnalysisModal from './components/AnalysisModal';

const PRESET_SOURCES: SourceOption[] = [
  { id: 'techmeme', name: 'Techmeme', domain: 'techmeme.com' },
  { id: 'verge', name: 'The Verge', domain: 'theverge.com' },
  { id: 'tc', name: 'TechCrunch', domain: 'techcrunch.com' },
  { id: 'hn', name: 'Hacker News', domain: 'news.ycombinator.com' },
  { id: 'ars', name: 'Ars Technica', domain: 'arstechnica.com' },
];

const ITEMS_PER_PAGE = 6;

const App: React.FC = () => {
  const [hasAuth, setHasAuth] = useState<boolean | null>(null);
  const [state, setState] = useState<NewsState>({
    items: [],
    sources: [],
    loading: true,
    error: null,
    lastUpdated: null
  });
  const [activeCategory, setActiveCategory] = useState<Category>('General');
  const [selectedSourceIds, setSelectedSourceIds] = useState<string[]>(['techmeme']);
  const [currentPage, setCurrentPage] = useState(1);

  // Analysis specific state
  const [selectedItem, setSelectedItem] = useState<NewsItem | null>(null);
  const [analysisData, setAnalysisData] = useState<AnalysisData | null>(null);
  const [isAnalysisLoading, setIsAnalysisLoading] = useState(false);

  const categories: Category[] = ['General', 'AI', 'Startups', 'Hardware', 'Software', 'Cybersecurity'];

  // Authentication check
  useEffect(() => {
    const checkAuth = async () => {
      // @ts-ignore
      const authorized = await window.aistudio.hasSelectedApiKey();
      setHasAuth(authorized);
    };
    checkAuth();
  }, []);

  const handleAuthorize = async () => {
    // @ts-ignore
    await window.aistudio.openSelectKey();
    setHasAuth(true); // Proceed assuming success per race condition mitigation rules
  };

  // Sort and paginate data
  const sortedItems = useMemo(() => {
    return [...state.items].sort((a, b) => b.relevance - a.relevance);
  }, [state.items]);

  const totalPages = Math.ceil(sortedItems.length / ITEMS_PER_PAGE);

  const paginatedItems = useMemo(() => {
    const startIndex = (currentPage - 1) * ITEMS_PER_PAGE;
    return sortedItems.slice(startIndex, startIndex + ITEMS_PER_PAGE);
  }, [sortedItems, currentPage]);

  const toggleSource = (id: string) => {
    setSelectedSourceIds(prev => 
      prev.includes(id) ? prev.filter(s => s !== id) : [...prev, id]
    );
    setCurrentPage(1);
  };

  const handleCategoryChange = (cat: Category) => {
    setActiveCategory(cat);
    setCurrentPage(1);
  };

  const loadNews = useCallback(async (cat: string, sourceIds: string[]) => {
    if (hasAuth === false) return;

    setState(prev => ({ ...prev, loading: true, error: null }));
    const domains = PRESET_SOURCES
      .filter(s => sourceIds.includes(s.id))
      .map(s => s.domain);

    try {
      const data = await fetchTechNews(cat, domains);
      setState({
        items: data.items,
        sources: data.sources,
        loading: false,
        error: null,
        lastUpdated: new Date().toLocaleTimeString([], { hour: '2-digit', minute: '2-digit' })
      });
    } catch (err: any) {
      if (err.message === "AUTH_REQUIRED") {
        setHasAuth(false);
      } else {
        setState(prev => ({ 
          ...prev, 
          loading: false, 
          error: err.message || 'An unexpected error occurred' 
        }));
      }
    }
  }, [hasAuth]);

  const handleOpenAnalysis = async (item: NewsItem) => {
    setSelectedItem(item);
    setIsAnalysisLoading(true);
    setAnalysisData(null);

    try {
      const analysis = await fetchDeepAnalysis(item);
      setAnalysisData(analysis);
    } catch (err: any) {
      if (err.message === "AUTH_REQUIRED") {
        setHasAuth(false);
        setSelectedItem(null);
      }
      console.error(err);
    } finally {
      setIsAnalysisLoading(false);
    }
  };

  const handleCloseAnalysis = () => {
    setSelectedItem(null);
    setAnalysisData(null);
  };

  useEffect(() => {
    if (hasAuth === true) {
      loadNews(activeCategory, selectedSourceIds);
    }
  }, [activeCategory, selectedSourceIds, loadNews, hasAuth]);

  // Auth Landing Screen
  if (hasAuth === false) {
    return (
      <div className="min-h-screen flex items-center justify-center bg-[#0f172a] p-6">
        <div className="max-w-md w-full glass p-10 rounded-[2.5rem] border border-white/10 text-center shadow-2xl relative overflow-hidden">
          <div className="absolute top-0 left-0 w-full h-1 bg-gradient-to-r from-blue-500 via-emerald-500 to-blue-500 animate-pulse" />

          <div className="w-20 h-20 bg-emerald-600 rounded-2xl flex items-center justify-center mx-auto mb-8 shadow-lg shadow-emerald-500/20 rotate-3">
            <span className="text-white font-black text-4xl">D</span>
          </div>

          <h1 className="text-3xl font-bold text-white mb-4 tracking-tight">Personal Digest Gate</h1>
          <p className="text-slate-400 mb-10 leading-relaxed text-sm">
            Welcome back. Please authorize your private instance to generate your personalized 24-hour daily digest.
          </p>

          <button
            onClick={handleAuthorize}
            className="w-full bg-emerald-600 hover:bg-emerald-500 text-white font-bold py-4 rounded-2xl transition-all active:scale-[0.98] shadow-lg shadow-emerald-600/20 flex items-center justify-center gap-3 mb-6"
          >
            <svg className="w-5 h-5" fill="none" stroke="currentColor" viewBox="0 0 24 24"><path strokeLinecap="round" strokeLinejoin="round" strokeWidth="2" d="M12 15v2m-6 4h12a2 2 0 002-2v-6a2 2 0 00-2-2H6a2 2 0 00-2 2v6a2 2 0 002 2zm10-10V7a4 4 0 00-8 0v4h8z"></path></svg>
            Unlock My Digest
          </button>

          <a 
            href="https://ai.google.dev/gemini-api/docs/billing" 
            target="_blank" 
            rel="noreferrer"
            className="text-[10px] text-slate-500 uppercase tracking-widest font-black hover:text-emerald-400 transition-colors"
          >
            Billing & Documentation
          </a>
        </div>
      </div>
    );
  }

  // Loading state for initial auth check
  if (hasAuth === null) {
    return (
      <div className="min-h-screen flex items-center justify-center">
        <div className="w-8 h-8 border-2 border-emerald-500/20 border-t-emerald-500 rounded-full animate-spin" />
      </div>
    );
  }

  return (
    <div className="min-h-screen pb-20">
      <AnalysisModal 
        item={selectedItem} 
        data={analysisData} 
        loading={isAnalysisLoading} 
        onClose={handleCloseAnalysis} 
      />

      <nav className="sticky top-0 z-50 glass border-b border-white/5 px-6 py-4 mb-8">
        <div className="max-w-7xl mx-auto flex flex-col md:flex-row md:items-center justify-between gap-4">
          <div className="flex items-center gap-2">
            <div className="w-8 h-8 bg-emerald-600 rounded-lg flex items-center justify-center shadow-lg shadow-emerald-500/20">
              <span className="text-white font-black text-lg">D</span>
            </div>
            <h1 className="text-xl font-bold tracking-tight bg-gradient-to-r from-white to-slate-400 bg-clip-text text-transparent">
              My Daily Digest
            </h1>
          </div>

          <div className="flex overflow-x-auto gap-2 no-scrollbar pb-1 md:pb-0">
            {categories.map((cat) => (
              <button
                key={cat}
                onClick={() => handleCategoryChange(cat)}
                className={`px-4 py-1.5 rounded-full text-sm font-medium transition-all whitespace-nowrap ${
                  activeCategory === cat
                    ? 'bg-emerald-600 text-white'
                    : 'text-slate-400 hover:text-white hover:bg-white/5'
                }`}
              >
                {cat}
              </button>
            ))}
          </div>
        </div>
      </nav>

      <main className="max-w-7xl mx-auto px-6">
        <header className="mb-10">
          <div className="flex flex-col md:flex-row md:items-end justify-between gap-6 mb-6">
            <div>
              <div className="flex items-center gap-3 mb-2">
                <h2 className="text-3xl font-bold text-white tracking-tight">Today's Technical Scan</h2>
                <div className="flex items-center gap-1.5 px-2 py-1 rounded-md bg-emerald-500/10 border border-emerald-500/20">
                  <span className="w-1.5 h-1.5 rounded-full bg-emerald-500 animate-pulse" />
                  <span className="text-[10px] font-black text-emerald-500 uppercase tracking-wider">Live Synthesis</span>
                </div>
              </div>
              <p className="text-slate-400 max-w-2xl leading-relaxed">
                A personal curation of the last 24 hours in tech. Sorted by industry gravity and impact.
              </p>
            </div>

            {state.lastUpdated && !state.loading && (
              <div className="flex items-center gap-2 text-slate-500 mono text-xs bg-white/5 px-3 py-1.5 rounded-lg border border-white/5">
                <svg className="w-3 h-3" fill="none" stroke="currentColor" viewBox="0 0 24 24"><path strokeLinecap="round" strokeLinejoin="round" strokeWidth="2" d="M4 4v5h.582m15.356 2A8.001 8.001 0 004.582 9m0 0H9m11 11v-5h-.581m0 0a8.003 8.003 0 01-15.357-2m15.357 2H15"></path></svg>
                Sync Time: {state.lastUpdated}
              </div>
            )}
          </div>

          <div className="flex flex-col gap-3">
            <span className="text-[10px] font-bold text-slate-500 uppercase tracking-[0.2em]">Primary Sources</span>
            <div className="flex flex-wrap gap-2">
              {PRESET_SOURCES.map((source) => (
                <button
                  key={source.id}
                  onClick={() => toggleSource(source.id)}
                  className={`flex items-center gap-2 px-3 py-1.5 rounded-lg border transition-all text-xs font-medium ${
                    selectedSourceIds.includes(source.id)
                      ? 'bg-emerald-500/20 border-emerald-500/50 text-emerald-200 shadow-[0_0_15px_rgba(16,185,129,0.1)]'
                      : 'bg-white/5 border-white/10 text-slate-400 hover:text-slate-200 hover:border-white/20'
                  }`}
                >
                  <img 
                    src={`https://www.google.com/s2/favicons?domain=${source.domain}`} 
                    className={`w-3 h-3 rounded-sm grayscale transition-all ${selectedSourceIds.includes(source.id) ? 'grayscale-0' : ''}`}
                    alt="" 
                  />
                  {source.name}
                  {selectedSourceIds.includes(source.id) && (
                    <svg className="w-3 h-3 text-emerald-400" fill="none" stroke="currentColor" viewBox="0 0 24 24"><path strokeLinecap="round" strokeLinejoin="round" strokeWidth="3" d="M5 13l4 4L19 7"></path></svg>
                  )}
                </button>
              ))}
            </div>
          </div>
        </header>

        {state.error && (
          <div className="bg-rose-500/10 border border-rose-500/30 p-5 rounded-2xl text-rose-400 flex items-center gap-4 mb-8">
            <div className="w-10 h-10 rounded-full bg-rose-500/20 flex items-center justify-center flex-shrink-0">
              <svg className="w-5 h-5" fill="none" stroke="currentColor" viewBox="0 0 24 24"><path strokeLinecap="round" strokeLinejoin="round" strokeWidth="2" d="M12 9v2m0 4h.01m-6.938 4h13.856c1.54 0 2.502-1.667 1.732-3L13.732 4c-.77-1.333-2.694-1.333-3.464 0L3.34 16c-.77 1.333.192 3 1.732 3z"></path></svg>
            </div>
            <div>
              <p className="font-bold">Sync Error</p>
              <p className="text-sm opacity-80">{state.error}</p>
            </div>
            <button 
              onClick={() => loadNews(activeCategory, selectedSourceIds)}
              className="ml-auto px-4 py-2 bg-rose-500/20 hover:bg-rose-500/30 rounded-lg text-sm font-bold transition-all"
            >
              Retry
            </button>
          </div>
        )}

        {state.loading ? (
          <div className="grid grid-cols-1 md:grid-cols-2 lg:grid-cols-3 gap-6">
            {[1, 2, 3, 4, 5, 6].map((i) => (
              <div key={i} className="glass rounded-2xl p-6 animate-pulse h-64 border border-white/5">
                <div className="h-4 w-1/4 bg-white/5 rounded mb-6"></div>
                <div className="h-6 w-3/4 bg-white/10 rounded mb-4"></div>
                <div className="h-4 w-full bg-white/5 rounded mb-2"></div>
                <div className="h-4 w-full bg-white/5 rounded mb-2"></div>
                <div className="h-4 w-2/3 bg-white/5 rounded mt-auto"></div>
              </div>
            ))}
          </div>
        ) : (
          <>
            <div className="grid grid-cols-1 md:grid-cols-2 lg:grid-cols-3 gap-6">
              {paginatedItems.map((item) => (
                <NewsCard key={item.id} item={item} onAnalyze={handleOpenAnalysis} />
              ))}
            </div>

            {totalPages > 1 && (
