  const yesterday = new Date(now.getTime() - (24 * 60 * 60 * 1000));

  const dateStringNow = now.toLocaleDateString('en-US', { year: 'numeric', month: 'long', day: 'numeric', hour: '2-digit', minute: '2-digit' });
  const dateStringYesterday = yesterday.toLocaleDateString('en-US', { year: 'numeric', month: 'long', day: 'numeric', hour: '2-digit', minute: '2-digit' });

  let categoryInstruction = "";
  const subCatText = subCategory !== 'All' ? `Specifically focusing on the sub-topic: ${subCategory}.` : "";

  if (category === 'Politics') {
    categoryInstruction = `Focus on political news concerning India, the European Union (EU), and the United States (US). ${subCatText}`;
  } else if (category === 'Geo-politics') {
    categoryInstruction = `Focus on international relations, global diplomacy, strategic alliances, and conflicts. ${subCatText}`;
  } else if (category === 'Finance') {
    categoryInstruction = `Focus on global markets, banking, economy, corporate shifts, and trade. ${subCatText}`;
  } else if (category === 'Technology') {
    categoryInstruction = `Focus on AI, Startups, Hardware, Software, Cybersecurity, and tech breakthroughs. ${subCatText}`;
  } else {
    categoryInstruction = `Provide critical global headlines across all major sectors. ${subCatText}`;
  }

  const prompt = `Provide a comprehensive list of EXACTLY 50 unique and critical news items from the LAST 24 HOURS (between ${dateStringYesterday} and ${dateStringNow}). 

  Category Focus: ${category}
  Instruction: ${categoryInstruction}

  Act as a world-class intelligence analyst. Provide a high-fidelity daily digest.
  Rank items by their systemic importance (1-10).

  MANDATORY: Provide exactly 50 distinct items.

  Structure the response as a JSON array of objects:
  - id: unique string
  - title: clear, impactful headline
  - summary: 1-2 concise sentences
  - category: exactly '${category}'
  - subCategory: the specific sub-topic if applicable
  - relevance: integer 1-10`;

  try {
    const response = await ai.models.generateContent({
      model: "gemini-3-flash-preview",
      contents: prompt,
      config: {
        tools: [{ googleSearch: {} }],
        responseMimeType: "application/json",
        responseSchema: {
          type: Type.ARRAY,
          items: {
            type: Type.OBJECT,
            properties: {
              id: { type: Type.STRING },
              title: { type: Type.STRING },
              summary: { type: Type.STRING },
              category: { type: Type.STRING },
              subCategory: { type: Type.STRING },
              relevance: { type: Type.INTEGER }
            },
            required: ["id", "title", "summary", "category", "relevance"]
          }
        }
      },
    });

    const items: NewsItem[] = JSON.parse(response.text);

    const sources: GroundingSource[] = [];
    const chunks = response.candidates?.[0]?.groundingMetadata?.groundingChunks;

    if (chunks) {
      chunks.forEach((chunk: any) => {
        if (chunk.web && chunk.web.uri && chunk.web.title) {
          sources.push({ title: chunk.web.title, uri: chunk.web.uri });
        }
      });
    }

    const uniqueSources = Array.from(new Map(sources.map(s => [s.uri, s])).values());
    return { items, sources: uniqueSources };
  } catch (error: any) {
    console.error("Gemini API Error:", error);
    if (error.message?.includes("Requested entity was not found")) {
      throw new Error("AUTH_REQUIRED");
    }
    throw new Error("Failed to fetch digest. Please try again.");
  }
};

export const fetchDeepAnalysis = async (item: NewsItem): Promise<AnalysisData> => {
  const ai = new GoogleGenAI({ apiKey: process.env.API_KEY || '' });

  const prompt = `Perform a strategic deep-dive into: "${item.title}". 
  Context: ${item.summary}

  Analysis required:
  1. Strategic Impact (marketImpact)
  2. Contextual Drivers (technicalContext)
  3. Risk & Future Outlook (futureOutlook)

  Return JSON with these 3 keys.`;

  try {
    const response = await ai.models.generateContent({
      model: "gemini-3-flash-preview",
      contents: prompt,
      config: {
        tools: [{ googleSearch: {} }],
        responseMimeType: "application/json",
        responseSchema: {
          type: Type.OBJECT,
          properties: {
            marketImpact: { type: Type.STRING },
            technicalContext: { type: Type.STRING },
            futureOutlook: { type: Type.STRING }
          },
          required: ["marketImpact", "technicalContext", "futureOutlook"]
        }
      },
    });

    const analysis = JSON.parse(response.text);
    const sources: GroundingSource[] = [];
    const chunks = response.candidates?.[0]?.groundingMetadata?.groundingChunks;

    if (chunks) {
      chunks.forEach((chunk: any) => {
        if (chunk.web && chunk.web.uri && chunk.web.title) {
          sources.push({ title: chunk.web.title, uri: chunk.web.uri });
        }
      });
    }

    return {
      ...analysis,
      sources: Array.from(new Map(sources.map(s => [s.uri, s])).values())
    };
  } catch (error: any) {
    console.error("Analysis Error:", error);
    if (error.message?.includes("Requested entity was not found")) {
      throw new Error("AUTH_REQUIRED");
    }
    throw new Error("Strategic analysis unavailable.");
  }
};

import React, { useState, useEffect, useCallback, useMemo } from 'react';
import { fetchTechNews, fetchDeepAnalysis } from './services/geminiService';
import { NewsItem, Category, NewsState, AnalysisData, SourceOption, SUB_CATEGORIES } from './types';
import NewsCard from './components/NewsCard';
import SourceList from './components/SourceList';
import AnalysisModal from './components/AnalysisModal';

const PRESET_SOURCES: SourceOption[] = [
  { id: 'techmeme', name: 'Techmeme', domain: 'techmeme.com' },
  { id: 'reuters', name: 'Reuters', domain: 'reuters.com' },
  { id: 'bloomberg', name: 'Bloomberg', domain: 'bloomberg.com' },
  { id: 'ap', name: 'AP News', domain: 'apnews.com' },
  { id: 'ft', name: 'Financial Times', domain: 'ft.com' },
  { id: 'thehindu', name: 'The Hindu', domain: 'thehindu.com' },
];

const ITEMS_PER_PAGE = 6;

const App: React.FC = () => {
  const [hasAuth, setHasAuth] = useState<boolean | null>(null);
  const [state, setState] = useState<NewsState>({
    items: [],
    sources: [],
    loading: true,
    error: null,
    lastUpdated: null
  });
  const [activeCategory, setActiveCategory] = useState<Category>('Top News');
  const [activeSubCategory, setActiveSubCategory] = useState<string>('All');
  const [selectedSourceIds, setSelectedSourceIds] = useState<string[]>([]);
  const [currentPage, setCurrentPage] = useState(1);

  const [selectedItem, setSelectedItem] = useState<NewsItem | null>(null);
  const [analysisData, setAnalysisData] = useState<AnalysisData | null>(null);
  const [isAnalysisLoading, setIsAnalysisLoading] = useState(false);

  const categories: Category[] = ['Top News', 'Politics', 'Geo-politics', 'Finance', 'Technology'];

  useEffect(() => {
    const checkAuth = async () => {
      // @ts-ignore
      const authorized = await window.aistudio.hasSelectedApiKey();
      setHasAuth(authorized);
    };
    checkAuth();
  }, []);

  const handleAuthorize = async () => {
    // @ts-ignore
    await window.aistudio.openSelectKey();
    setHasAuth(true);
  };

  const sortedItems = useMemo(() => {
    return [...state.items].sort((a, b) => b.relevance - a.relevance);
  }, [state.items]);

  const totalPages = Math.ceil(sortedItems.length / ITEMS_PER_PAGE);

  const paginatedItems = useMemo(() => {
    const startIndex = (currentPage - 1) * ITEMS_PER_PAGE;
    return sortedItems.slice(startIndex, startIndex + ITEMS_PER_PAGE);
  }, [sortedItems, currentPage]);

  const toggleSource = (id: string) => {
    setSelectedSourceIds(prev => 
      prev.includes(id) ? prev.filter(s => s !== id) : [...prev, id]
    );
    setCurrentPage(1);
  };

  const handleCategoryChange = (cat: Category) => {
    setActiveCategory(cat);
    setActiveSubCategory('All'); // Reset sub-category on main category change
    setCurrentPage(1);
  };

  const handleSubCategoryChange = (sub: string) => {
    setActiveSubCategory(sub);
    setCurrentPage(1);
  };

  const loadNews = useCallback(async (cat: Category, subCat: string, sourceIds: string[]) => {
    if (hasAuth === false) return;

    setState(prev => ({ ...prev, loading: true, error: null }));
    const domains = PRESET_SOURCES
      .filter(s => sourceIds.includes(s.id))
      .map(s => s.domain);

    try {
      const data = await fetchTechNews(cat, subCat, domains);
      setState({
        items: data.items,
        sources: data.sources,
        loading: false,
        error: null,
        lastUpdated: new Date().toLocaleTimeString([], { hour: '2-digit', minute: '2-digit' })
      });
    } catch (err: any) {
      if (err.message === "AUTH_REQUIRED") {
        setHasAuth(false);
      } else {
        setState(prev => ({ 
          ...prev, 
          loading: false, 
          error: err.message || 'An unexpected error occurred' 
        }));
      }
    }
  }, [hasAuth]);

  const handleOpenAnalysis = async (item: NewsItem) => {
    setSelectedItem(item);
    setIsAnalysisLoading(true);
    setAnalysisData(null);

    try {
      const analysis = await fetchDeepAnalysis(item);
      setAnalysisData(analysis);
    } catch (err: any) {
      if (err.message === "AUTH_REQUIRED") {
        setHasAuth(false);
        setSelectedItem(null);
      }
      console.error(err);
    } finally {
      setIsAnalysisLoading(false);
    }
  };

  const handleCloseAnalysis = () => {
    setSelectedItem(null);
    setAnalysisData(null);
  };

  useEffect(() => {
    if (hasAuth === true) {
      loadNews(activeCategory, activeSubCategory, selectedSourceIds);
    }
  }, [activeCategory, activeSubCategory, selectedSourceIds, loadNews, hasAuth]);

  if (hasAuth === false) {
    return (
      <div className="min-h-screen flex items-center justify-center bg-[#0f172a] p-6">
        <div className="max-w-md w-full glass p-10 rounded-[2.5rem] border border-white/10 text-center shadow-2xl relative overflow-hidden">
          <div className="absolute top-0 left-0 w-full h-1 bg-gradient-to-r from-emerald-500 via-blue-500 to-emerald-500 animate-pulse" />
          <div className="w-20 h-20 bg-emerald-600 rounded-2xl flex items-center justify-center mx-auto mb-8 shadow-lg shadow-emerald-500/20 rotate-3">
            <span className="text-white font-black text-4xl">D</span>
          </div>
          <h1 className="text-3xl font-bold text-white mb-4 tracking-tight">Personal Digest Gate</h1>
          <p className="text-slate-400 mb-10 leading-relaxed text-sm">
            Unlock your daily global intelligence report across politics, finance, world affairs, and technology.
          </p>
          <button
            onClick={handleAuthorize}
            className="w-full bg-emerald-600 hover:bg-emerald-500 text-white font-bold py-4 rounded-2xl transition-all active:scale-[0.98] shadow-lg shadow-emerald-600/20 flex items-center justify-center gap-3 mb-6"
          >
            Unlock My Digest
          </button>
        </div>
      </div>
    );
  }

  if (hasAuth === null) {
    return (
      <div className="min-h-screen flex items-center justify-center">
        <div className="w-8 h-8 border-2 border-emerald-500/20 border-t-emerald-500 rounded-full animate-spin" />
      </div>
    );
  }

  return (
    <div className="min-h-screen pb-20">
      <AnalysisModal 
        item={selectedItem} 
        data={analysisData} 
        loading={isAnalysisLoading} 
        onClose={handleCloseAnalysis} 
      />

      <nav className="sticky top-0 z-50 glass border-b border-white/5 px-6 py-4 mb-2">
        <div className="max-w-7xl mx-auto flex flex-col md:flex-row md:items-center justify-between gap-4">
          <div className="flex items-center gap-2">
            <div className="w-8 h-8 bg-emerald-600 rounded-lg flex items-center justify-center">
              <span className="text-white font-black text-lg">D</span>
            </div>
            <h1 className="text-xl font-bold tracking-tight text-white">My Daily Digest</h1>
          </div>
          <div className="flex overflow-x-auto gap-2 no-scrollbar pb-1 md:pb-0">
            {categories.map((cat) => (
              <button
                key={cat}
                onClick={() => handleCategoryChange(cat)}
                className={`px-4 py-1.5 rounded-full text-sm font-medium transition-all whitespace-nowrap ${
                  activeCategory === cat
                    ? 'bg-emerald-600 text-white shadow-lg shadow-emerald-600/20'
                    : 'text-slate-400 hover:text-white hover:bg-white/5'
                }`}
              >
                {cat}
              </button>
            ))}
          </div>
        </div>
      </nav>

      {/* Sub-Category Navigation */}
      <div className="glass border-b border-white/5 px-6 py-3 mb-8 sticky top-[73px] z-40 bg-slate-900/40 backdrop-blur-xl">
        <div className="max-w-7xl mx-auto flex items-center gap-4 overflow-x-auto no-scrollbar">
          <span className="text-[10px] font-black text-slate-500 uppercase tracking-widest flex-shrink-0">Filters:</span>
          {SUB_CATEGORIES[activeCategory].map((sub) => (
            <button
              key={sub}
              onClick={() => handleSubCategoryChange(sub)}
              className={`px-3 py-1 rounded-lg text-xs font-semibold transition-all whitespace-nowrap border ${
                activeSubCategory === sub
                  ? 'bg-slate-700 border-emerald-500/50 text-emerald-400 shadow-sm'
                  : 'bg-transparent border-transparent text-slate-500 hover:text-slate-300'
              }`}
            >
              {sub}
            </button>
          ))}
        </div>
      </div>

      <main className="max-w-7xl mx-auto px-6">
        <header className="mb-10">
          <div className="flex flex-col md:flex-row md:items-end justify-between gap-6 mb-6">
            <div>
              <div className="flex items-center gap-3 mb-2">
                <h2 className="text-3xl font-bold text-white tracking-tight">
                  {activeSubCategory !== 'All' ? `${activeSubCategory} | ` : ''}{activeCategory}
                </h2>
                <div className="flex items-center gap-1.5 px-2 py-1 rounded-md bg-emerald-500/10 border border-emerald-500/20">
                  <span className="w-1.5 h-1.5 rounded-full bg-emerald-500 animate-pulse" />
                  <span className="text-[10px] font-black text-emerald-500 uppercase tracking-wider">Live Scan</span>
                </div>
              </div>
              <p className="text-slate-400 max-w-2xl leading-relaxed text-sm">
                Dedicated daily brief for {activeSubCategory === 'All' ? `global ${activeCategory.toLowerCase()}` : activeSubCategory}.
              </p>
            </div>
            {state.lastUpdated && !state.loading && (
              <div className="text-slate-500 mono text-xs bg-white/5 px-3 py-1.5 rounded-lg border border-white/5">
                Last Sync: {state.lastUpdated}
              </div>
            )}
          </div>
          <div className="flex flex-wrap gap-2">
            {PRESET_SOURCES.map((source) => (
              <button
                key={source.id}
                onClick={() => toggleSource(source.id)}
                className={`flex items-center gap-2 px-3 py-1.5 rounded-lg border transition-all text-xs font-medium ${
                  selectedSourceIds.includes(source.id)
                    ? 'bg-emerald-500/20 border-emerald-500/50 text-emerald-200'
                    : 'bg-white/5 border-white/10 text-slate-400 hover:border-white/20'
                }`}
              >
                <img src={`https://www.google.com/s2/favicons?domain=${source.domain}`} className="w-3 h-3 rounded-sm" alt="" />
                {source.name}
              </button>
            ))}
          </div>
        </header>

        {state.loading ? (
          <div className="grid grid-cols-1 md:grid-cols-2 lg:grid-cols-3 gap-6">
            {[1, 2, 3, 4, 5, 6].map((i) => (
              <div key={i} className="glass rounded-2xl p-6 animate-pulse h-64 border border-white/5" />
            ))}
          </div>
        ) : (
          <>
            <div className="grid grid-cols-1 md:grid-cols-2 lg:grid-cols-3 gap-6">
              {paginatedItems.map((item) => (
                <NewsCard key={item.id} item={item} onAnalyze={handleOpenAnalysis} />
              ))}
            </div>
            {totalPages > 1 && (
              <div className="mt-12 flex items-center justify-center gap-1">
                {Array.from({ length: totalPages }, (_, i) => i + 1).map(page => (
                  <button
                    key={page}
                    onClick={() => setCurrentPage(page)}
                    className={`w-10 h-10 rounded-lg border transition-all text-xs font-bold ${
                      currentPage === page ? 'bg-emerald-600 border-emerald-500 text-white' : 'border-white/10 text-slate-400 hover:bg-white/5'
                    }`}
                  >
                    {page}
                  </button>
                ))}
