    { id: 'techcrunch', name: 'TechCrunch', domain: 'techcrunch.com' },
    { id: 'theverge', name: 'The Verge', domain: 'theverge.com' },
    { id: 'arstechnica', name: 'Ars Technica', domain: 'arstechnica.com' },
  ]
};

const ITEMS_PER_PAGE = 6;

const App: React.FC = () => {
  const [hasAuth, setHasAuth] = useState<boolean | null>(null);
  const [state, setState] = useState<NewsState>({
    items: [],
    sources: [],
    loading: true,
    error: null,
    lastUpdated: null
  });

  const [activeCategory, setActiveCategory] = useState<Category>('Top News');
  const [activeSubCategory, setActiveSubCategory] = useState<string>('All');

  const [categorySources, setCategorySources] = useState<Record<Category, string[]>>({
    'Top News': [],
    'Politics': [],
    'Geo-politics': [],
    'Finance': [],
    'Technology': []
  });

  const [currentPage, setCurrentPage] = useState(1);
  const [selectedItem, setSelectedItem] = useState<NewsItem | null>(null);
  const [analysisData, setAnalysisData] = useState<AnalysisData | null>(null);
  const [isAnalysisLoading, setIsAnalysisLoading] = useState(false);

  const categories: Category[] = ['Top News', 'Politics', 'Geo-politics', 'Finance', 'Technology'];

  useEffect(() => {
    const checkAuth = async () => {
      // @ts-ignore
      const authorized = await window.aistudio.hasSelectedApiKey();
      setHasAuth(authorized);
    };
    checkAuth();
  }, []);

  const handleAuthorize = async () => {
    // @ts-ignore
    await window.aistudio.openSelectKey();
    setHasAuth(true);
  };

  const sortedItems = useMemo(() => {
    return [...state.items].sort((a, b) => b.relevance - a.relevance);
  }, [state.items]);

  const totalPages = Math.ceil(sortedItems.length / ITEMS_PER_PAGE);

  const paginatedItems = useMemo(() => {
    const startIndex = (currentPage - 1) * ITEMS_PER_PAGE;
    return sortedItems.slice(startIndex, startIndex + ITEMS_PER_PAGE);
  }, [sortedItems, currentPage]);

  const toggleSource = (id: string) => {
    setCategorySources(prev => ({
      ...prev,
      [activeCategory]: prev[activeCategory].includes(id) 
        ? prev[activeCategory].filter(s => s !== id) 
        : [...prev[activeCategory], id]
    }));
    setCurrentPage(1);
  };

  const handleCategoryChange = (cat: Category) => {
    setActiveCategory(cat);
    setActiveSubCategory('All');
    setCurrentPage(1);
  };

  const handleSubCategoryChange = (sub: string) => {
    setActiveSubCategory(sub);
    setCurrentPage(1);
  };

  const loadNews = useCallback(async (cat: Category, subCat: string, sourceIds: string[]) => {
    if (hasAuth === false) return;

    setState(prev => ({ ...prev, loading: true, error: null }));

    const currentPresetSources = PRESET_SOURCES_MAP[cat];
    const domains = currentPresetSources
      .filter(s => sourceIds.includes(s.id))
      .map(s => s.domain);

    try {
      const data = await fetchTechNews(cat, subCat, domains);
      setState({
        items: data.items,
        sources: data.sources,
        loading: false,
        error: null,
        lastUpdated: new Date().toLocaleTimeString([], { hour: '2-digit', minute: '2-digit' })
      });
    } catch (err: any) {
      if (err.message === "AUTH_REQUIRED") {
        setHasAuth(false);
      } else {
        setState(prev => ({ 
          ...prev, 
          loading: false, 
          error: err.message || 'An unexpected error occurred' 
        }));
      }
    }
  }, [hasAuth]);

  const handleOpenAnalysis = async (item: NewsItem) => {
    setSelectedItem(item);
    setIsAnalysisLoading(true);
    setAnalysisData(null);

    try {
      const analysis = await fetchDeepAnalysis(item);
      setAnalysisData(analysis);
    } catch (err: any) {
      if (err.message === "AUTH_REQUIRED") {
        setHasAuth(false);
        setSelectedItem(null);
      }
      console.error(err);
    } finally {
      setIsAnalysisLoading(false);
    }
  };

  const handleCloseAnalysis = () => {
    setSelectedItem(null);
    setAnalysisData(null);
  };

  useEffect(() => {
    if (hasAuth === true) {
      loadNews(activeCategory, activeSubCategory, categorySources[activeCategory]);
    }
  }, [activeCategory, activeSubCategory, categorySources, loadNews, hasAuth]);

  if (hasAuth === false) {
    return (
      <div className="min-h-screen flex items-center justify-center bg-[#0f172a] p-6">
        <div className="max-w-md w-full glass p-10 rounded-[2.5rem] border border-white/10 text-center shadow-2xl relative overflow-hidden">
          <div className="absolute top-0 left-0 w-full h-1 bg-gradient-to-r from-emerald-500 via-blue-500 to-emerald-500 animate-pulse" />
          <div className="w-20 h-20 bg-emerald-600 rounded-2xl flex items-center justify-center mx-auto mb-8 shadow-lg shadow-emerald-500/20 rotate-3">
            <span className="text-white font-black text-4xl">D</span>
          </div>
          <h1 className="text-3xl font-bold text-white mb-4 tracking-tight">Access Authority</h1>
          <p className="text-slate-400 mb-10 leading-relaxed text-sm">
            Unlock your daily scan of open-access global news and strategic technical analysis.
          </p>
          <button
            onClick={handleAuthorize}
            className="w-full bg-emerald-600 hover:bg-emerald-500 text-white font-bold py-4 rounded-2xl transition-all active:scale-[0.98] shadow-lg shadow-emerald-600/20 flex items-center justify-center gap-3 mb-6"
          >
            Authorize News Feed
          </button>
        </div>
      </div>
    );
  }

  if (hasAuth === null) {
    return (
      <div className="min-h-screen flex items-center justify-center">
        <div className="w-8 h-8 border-2 border-emerald-500/20 border-t-emerald-500 rounded-full animate-spin" />
      </div>
    );
  }

  return (
    <div className="min-h-screen pb-20">
      <AnalysisModal 
        item={selectedItem} 
        data={analysisData} 
        loading={isAnalysisLoading} 
        onClose={handleCloseAnalysis} 
      />

      <nav className="sticky top-0 z-50 glass border-b border-white/5 px-6 py-4 mb-2">
        <div className="max-w-7xl mx-auto flex flex-col md:flex-row md:items-center justify-between gap-4">
          <div className="flex items-center gap-2">
            <div className="w-8 h-8 bg-emerald-600 rounded-lg flex items-center justify-center">
              <span className="text-white font-black text-lg">D</span>
            </div>
            <h1 className="text-xl font-bold tracking-tight text-white">My Daily Digest</h1>
          </div>
          <div className="flex overflow-x-auto gap-2 no-scrollbar pb-1 md:pb-0">
            {categories.map((cat) => (
              <button
                key={cat}
                onClick={() => handleCategoryChange(cat)}
                className={`px-4 py-1.5 rounded-full text-sm font-medium transition-all whitespace-nowrap ${
                  activeCategory === cat
                    ? 'bg-emerald-600 text-white shadow-lg shadow-emerald-600/20'
                    : 'text-slate-400 hover:text-white hover:bg-white/5'
                }`}
              >
                {cat}
              </button>
            ))}
          </div>
        </div>
      </nav>

      <div className="glass border-b border-white/5 px-6 py-3 mb-8 sticky top-[73px] z-40 bg-slate-900/40 backdrop-blur-xl">
        <div className="max-w-7xl mx-auto flex items-center gap-4 overflow-x-auto no-scrollbar">
          <span className="text-[10px] font-black text-slate-500 uppercase tracking-widest flex-shrink-0">Filter Topic:</span>
          {SUB_CATEGORIES[activeCategory].map((sub) => (
            <button
              key={sub}
              onClick={() => handleSubCategoryChange(sub)}
              className={`px-3 py-1 rounded-lg text-xs font-semibold transition-all whitespace-nowrap border ${
                activeSubCategory === sub
                  ? 'bg-slate-700 border-emerald-500/50 text-emerald-400'
                  : 'bg-transparent border-transparent text-slate-500 hover:text-slate-300'
              }`}
            >
              {sub}
            </button>
          ))}
        </div>
      </div>

      <main className="max-w-7xl mx-auto px-6">
        <header className="mb-10">
          <div className="flex flex-col md:flex-row md:items-end justify-between gap-6 mb-6">
            <div>
              <div className="flex items-center gap-3 mb-2">
                <h2 className="text-3xl font-bold text-white tracking-tight">
                  {activeSubCategory !== 'All' ? `${activeSubCategory} ` : ''}{activeCategory}
                </h2>
                <div className="flex items-center gap-1.5 px-2 py-1 rounded-md bg-emerald-500/10 border border-emerald-500/20">
