              </p>
            </div>
            {state.lastUpdated && !state.loading && (
              <div className="text-slate-500 mono text-xs bg-white/5 px-3 py-1.5 rounded-lg border border-white/5">
                Timestamp: {state.lastUpdated}
              </div>
