import { GoogleGenAI, Type } from "@google/genai";
import { NewsItem, GroundingSource, AnalysisData } from "../types";

export const fetchTechNews = async (
  category: string = 'Top News', 
  subCategory: string = 'All',
  preferredSources: string[] = []
): Promise<{ items: NewsItem[], sources: GroundingSource[] }> => {
  const ai = new GoogleGenAI({ apiKey: process.env.API_KEY || '' });

  const now = new Date();
  const yesterday = new Date(now.getTime() - (24 * 60 * 60 * 1000));

  const dateStringNow = now.toLocaleDateString('en-US', { year: 'numeric', month: 'long', day: 'numeric', hour: '2-digit', minute: '2-digit' });
  const dateStringYesterday = yesterday.toLocaleDateString('en-US', { year: 'numeric', month: 'long', day: 'numeric', hour: '2-digit', minute: '2-digit' });

  let categoryInstruction = "";
  const subCatText = subCategory !== 'All' ? `Specifically focusing on the sub-topic: ${subCategory}.` : "";
  const sourceText = preferredSources.length > 0 
    ? `IMPORTANT: Prioritize and cross-reference news primarily from these domains: ${preferredSources.join(', ')}.` 
    : "";

  if (category === 'Politics') {
    categoryInstruction = `Focus on political news concerning India, the European Union (EU), and the United States (US). ${subCatText}`;
  } else if (category === 'Geo-politics') {
    categoryInstruction = `Focus on international relations, global diplomacy, strategic alliances, and conflicts. ${subCatText}`;
  } else if (category === 'Markets') {
    categoryInstruction = `Focus on stock market performance, global indices (S&P 500, Nifty, etc.), commodities, and specific ticker news. ${subCatText}`;
  } else if (category === 'Finance') {
    categoryInstruction = `Focus on global banking, macroeconomic trends, corporate earnings, fintech, and general economy news. ${subCatText}`;
  } else if (category === 'Technology') {
    categoryInstruction = `Focus on AI, Startups, Hardware, Software, Cybersecurity, and tech breakthroughs. ${subCatText}`;
  } else {
    categoryInstruction = `Provide critical global headlines across all major sectors. ${subCatText}`;
  }

  const prompt = `Provide a comprehensive list of EXACTLY 50 unique and critical news items from the LAST 24 HOURS (between ${dateStringYesterday} and ${dateStringNow}). 

  Category Focus: ${category}
  Instruction: ${categoryInstruction}
  ${sourceText}

  Act as a world-class intelligence analyst. Provide a high-fidelity daily digest.
  Rank items by their systemic importance (1-10).

  MANDATORY: Provide exactly 50 distinct items.

  Structure the response as a JSON array of objects:
  - id: unique string
  - title: clear, impactful headline
  - summary: 1-2 concise sentences
  - category: exactly '${category}'
  - subCategory: the specific sub-topic if applicable
  - relevance: integer 1-10`;

  try {
    const response = await ai.models.generateContent({
      model: "gemini-3-flash-preview",
      contents: prompt,
      config: {
        tools: [{ googleSearch: {} }],
        responseMimeType: "application/json",
        responseSchema: {
          type: Type.ARRAY,
          items: {
            type: Type.OBJECT,
            properties: {
              id: { type: Type.STRING },
              title: { type: Type.STRING },
              summary: { type: Type.STRING },
              category: { type: Type.STRING },
              subCategory: { type: Type.STRING },
              relevance: { type: Type.INTEGER }
            },
            required: ["id", "title", "summary", "category", "relevance"]
          }
        }
      },
    });

    const items: NewsItem[] = JSON.parse(response.text);

    const sources: GroundingSource[] = [];
    const chunks = response.candidates?.[0]?.groundingMetadata?.groundingChunks;

    if (chunks) {
      chunks.forEach((chunk: any) => {
        if (chunk.web && chunk.web.uri && chunk.web.title) {
          sources.push({ title: chunk.web.title, uri: chunk.web.uri });
        }
      });
    }

    const uniqueSources = Array.from(new Map(sources.map(s => [s.uri, s])).values());
    return { items, sources: uniqueSources };
  } catch (error: any) {
    console.error("Gemini API Error:", error);
    if (error.message?.includes("Requested entity was not found")) {
      throw new Error("AUTH_REQUIRED");
    }
    throw new Error("Failed to fetch digest. Please try again.");
  }
};

export const fetchDeepAnalysis = async (item: NewsItem): Promise<AnalysisData> => {
  const ai = new GoogleGenAI({ apiKey: process.env.API_KEY || '' });

  const prompt = `Perform a strategic deep-dive into: "${item.title}". 
  Context: ${item.summary}

  Analysis required:
  1. Strategic Impact (marketImpact)
  2. Contextual Drivers (technicalContext)
  3. Risk & Future Outlook (futureOutlook)

  Return JSON with these 3 keys.`;

  try {
    const response = await ai.models.generateContent({
      model: "gemini-3-flash-preview",
      contents: prompt,
      config: {
        tools: [{ googleSearch: {} }],
        responseMimeType: "application/json",
        responseSchema: {
          type: Type.OBJECT,
          properties: {
            marketImpact: { type: Type.STRING },
            technicalContext: { type: Type.STRING },
            futureOutlook: { type: Type.STRING }
          },
          required: ["marketImpact", "technicalContext", "futureOutlook"]
        }
      },
    });

    const analysis = JSON.parse(response.text);
    const sources: GroundingSource[] = [];
    const chunks = response.candidates?.[0]?.groundingMetadata?.groundingChunks;

    if (chunks) {
      chunks.forEach((chunk: any) => {
        if (chunk.web && chunk.web.uri && chunk.web.title) {
          sources.push({ title: chunk.web.title, uri: chunk.web.uri });
        }
      });
    }

    return {
      ...analysis,
      sources: Array.from(new Map(sources.map(s => [s.uri, s])).values())
    };
  } catch (error: any) {
    console.error("Analysis Error:", error);
    if (error.message?.includes("Requested entity was not found")) {
      throw new Error("AUTH_REQUIRED");
    }
    throw new Error("Strategic analysis unavailable.");
  }
};

