  title: string;
  summary: string;
  category: string;
  subCategory?: string;
  relevance: number;
}

export interface GroundingSource {
  title: string;
  uri: string;
}

export interface AnalysisData {
  marketImpact: string;
  technicalContext: string;
  futureOutlook: string;
  sources: GroundingSource[];
}

export interface SourceOption {
