import { GoogleGenAI, Type } from "@google/genai";
import { NewsItem, GroundingSource, AnalysisData } from "../types";

export const fetchTechNews = async (
  category: string = 'Technology', 
  subCategory: string = 'All',
  preferredSources: string[] = []
): Promise<{ items: NewsItem[], sources: GroundingSource[] }> => {
  // Use process.env.API_KEY directly as per guidelines
  const ai = new GoogleGenAI({ apiKey: process.env.API_KEY });

  const now = new Date();
  const yesterday = new Date(now.getTime() - (24 * 60 * 60 * 1000));

  const dateStringNow = now.toLocaleDateString('en-US', { year: 'numeric', month: 'long', day: 'numeric', hour: '2-digit', minute: '2-digit' });
  const dateStringYesterday = yesterday.toLocaleDateString('en-US', { year: 'numeric', month: 'long', day: 'numeric', hour: '2-digit', minute: '2-digit' });

  let categoryInstruction = "";
  const subCatText = subCategory !== 'All' ? `Specifically focusing on the sub-topic: ${subCategory}.` : "";

  // Stricter source instruction
  const sourceText = preferredSources.length > 0 
    ? `CRITICAL: You MUST ONLY return news items that originated from or are reported by these specific domains: ${preferredSources.join(', ')}. If a story is not covered by these sources, do not include it.` 
    : "You may use any reputable global news sources.";

  if (category === 'Politics') {
    categoryInstruction = `Focus on high-stakes political news concerning India, the European Union (EU), and the United States (US). ${subCatText}`;
  } else if (category === 'Geo-politics') {
    categoryInstruction = `Focus on strategic international relations, global diplomacy shifts, and major geopolitical conflicts. ${subCatText}`;
  } else if (category === 'Markets') {
    categoryInstruction = `Focus on major stock market movements, global indices (S&P 500, Nifty, etc.), commodities, and market-moving corporate events. ${subCatText}`;
  } else if (category === 'Finance') {
    categoryInstruction = `Focus on systemic banking shifts, macroeconomic policy changes, corporate earnings of giants, and major fintech developments. ${subCatText}`;
  } else if (category === 'Technology') {
    categoryInstruction = `Focus on industry-shaping AI, strategic startup acquisitions, massive hardware/software breakthroughs, and critical cybersecurity events. ${subCatText}`;
  } else {
    categoryInstruction = `Provide only critical headlines for the selected sector. ${subCatText}`;
  }

  const prompt = `Provide a comprehensive list of EXACTLY 50 unique and impact-focused news items from the LAST 24 HOURS (between ${dateStringYesterday} and ${dateStringNow}). 

  Category Focus: ${category}
  Instruction: ${categoryInstruction}
  Source Constraint: ${sourceText}

  Act as a world-class intelligence analyst. Your goal is to synthesize information that can be consumed quickly. 
  Rank items by their systemic importance (Relevance: 1-10). 
  Items with a relevance of 5 or higher are considered noteworthy for this digest.

  MANDATORY: Provide exactly 50 distinct items. If the source constraint limits you, still try to find 50, but priority is accuracy to the source constraint.

  Structure the response as a JSON array of objects:
  - id: unique string
  - title: clear, impactful headline
  - summary: 1-2 concise sentences
  - category: exactly '${category}'
  - subCategory: the specific sub-topic (topic category) if applicable
  - source: the primary publisher name (e.g. "TechCrunch", "Reuters", "Moneycontrol")
  - relevance: integer 1-10`;

  try {
    const response = await ai.models.generateContent({
      model: "gemini-3-flash-preview",
      contents: prompt,
      config: {
        tools: [{ googleSearch: {} }],
        responseMimeType: "application/json",
        responseSchema: {
          type: Type.ARRAY,
          items: {
            type: Type.OBJECT,
            properties: {
              id: { type: Type.STRING },
              title: { type: Type.STRING },
              summary: { type: Type.STRING },
              category: { type: Type.STRING },
              subCategory: { type: Type.STRING },
              source: { type: Type.STRING },
              relevance: { type: Type.INTEGER }
            },
            required: ["id", "title", "summary", "category", "source", "relevance"]
          }
        }
      },
    });

    const items: NewsItem[] = JSON.parse(response.text || "[]");

    const sources: GroundingSource[] = [];
    const chunks = response.candidates?.[0]?.groundingMetadata?.groundingChunks;

    if (chunks) {
      chunks.forEach((chunk: any) => {
        if (chunk.web && chunk.web.uri && chunk.web.title) {
          sources.push({ title: chunk.web.title, uri: chunk.web.uri });
        }
      });
    }

    const uniqueSources = Array.from(new Map(sources.map(s => [s.uri, s])).values());
    return { items, sources: uniqueSources };
  } catch (error: any) {
    console.error("Gemini API Error:", error);
    if (error.message?.includes("Requested entity was not found")) {
      throw new Error("AUTH_REQUIRED");
    }
    throw new Error("Failed to fetch digest. Please try again.");
  }
};

export const fetchDeepAnalysis = async (item: NewsItem): Promise<AnalysisData> => {
  const ai = new GoogleGenAI({ apiKey: process.env.API_KEY });

  const prompt = `Perform a strategic deep-dive into: "${item.title}". 
  Context: ${item.summary}

  Analysis required:
  1. Strategic Impact (marketImpact)
  2. Contextual Drivers (technicalContext)
  3. Risk & Future Outlook (futureOutlook)

  Return JSON with these 3 keys.`;

  try {
    const response = await ai.models.generateContent({
      model: "gemini-3-flash-preview",
      contents: prompt,
      config: {
        tools: [{ googleSearch: {} }],
        responseMimeType: "application/json",
        responseSchema: {
          type: Type.OBJECT,
          properties: {
            marketImpact: { type: Type.STRING },
            technicalContext: { type: Type.STRING },
            futureOutlook: { type: Type.STRING }
          },
          required: ["marketImpact", "technicalContext", "futureOutlook"]
        }
      },
    });

    const analysis = JSON.parse(response.text || "{}");

    const sources: GroundingSource[] = [];
    const chunks = response.candidates?.[0]?.groundingMetadata?.groundingChunks;

    if (chunks) {
      chunks.forEach((chunk: any) => {
        if (chunk.web && chunk.web.uri && chunk.web.title) {
          sources.push({ title: chunk.web.title, uri: chunk.web.uri });
        }
      });
    }

    const uniqueSources = Array.from(new Map(sources.map(s => [s.uri, s])).values());

    return {
      marketImpact: analysis.marketImpact || "No analysis available.",
      technicalContext: analysis.technicalContext || "No context available.",
      futureOutlook: analysis.futureOutlook || "No outlook available.",
      sources: uniqueSources
    };
  } catch (error: any) {
