const ITEMS_PER_PAGE = 12;
const HIGH_SIG_THRESHOLD = 5;
const CACHE_TTL = 30 * 60 * 1000; // 30 minutes in milliseconds

interface CachedData {
  items: NewsItem[];
  sources: GroundingSource[];
  timestamp: number;
  lastUpdatedStr: string;
}

const App: React.FC = () => {
  const [hasAuth, setHasAuth] = useState<boolean | null>(null);
  const [state, setState] = useState<NewsState>({
    items: [],
    sources: [],
    loading: true,
    error: null,
    lastUpdated: null
  });
  const [isFromCache, setIsFromCache] = useState(false);

  const [activeCategory, setActiveCategory] = useState<Category>('Technology');
  const [activeSubCategory, setActiveSubCategory] = useState<string>('All');

  const [categorySources, setCategorySources] = useState<Record<Category, string[]>>({
    'Technology': [],
    'Markets': [],
    'Finance': [],
    'Politics': [],
    'Geo-politics': []
  });

  const [currentPage, setCurrentPage] = useState(1);
  const [selectedItem, setSelectedItem] = useState<NewsItem | null>(null);
  const [analysisData, setAnalysisData] = useState<AnalysisData | null>(null);
  const [isAnalysisLoading, setIsAnalysisLoading] = useState(false);

  const categories: Category[] = ['Technology', 'Markets', 'Finance', 'Politics', 'Geo-politics'];

  useEffect(() => {
    const checkAuth = async () => {
      // @ts-ignore
      const authorized = await window.aistudio.hasSelectedApiKey();
      setHasAuth(authorized);
    };
    checkAuth();
  }, []);

  const handleAuthorize = async () => {
    // @ts-ignore
    await window.aistudio.openSelectKey();
    setHasAuth(true);
  };

  const sortedItems = useMemo(() => {
    let filtered = state.items.filter(item => item.relevance >= HIGH_SIG_THRESHOLD);

    const selectedIds = categorySources[activeCategory];
    if (selectedIds.length > 0) {
      const selectedNames = PRESET_SOURCES_MAP[activeCategory]
        .filter(s => selectedIds.includes(s.id))
        .map(s => s.name.toLowerCase());

      filtered = filtered.filter(item => {
        const itemSource = item.source.toLowerCase();
        return selectedNames.some(name => itemSource.includes(name) || name.includes(itemSource));
      });
    }

    return filtered.sort((a, b) => b.relevance - a.relevance);
  }, [state.items, activeCategory, categorySources]);

  const totalPages = Math.ceil(sortedItems.length / ITEMS_PER_PAGE);

  const paginatedItems = useMemo(() => {
    const startIndex = (currentPage - 1) * ITEMS_PER_PAGE;
    return sortedItems.slice(startIndex, startIndex + ITEMS_PER_PAGE);
  }, [sortedItems, currentPage]);

  const toggleSource = (id: string) => {
    setCategorySources(prev => ({
      ...prev,
      [activeCategory]: prev[activeCategory].includes(id) 
        ? prev[activeCategory].filter(s => s !== id) 
        : [...prev[activeCategory], id]
    }));
    setCurrentPage(1);
  };

  const handleCategoryChange = (cat: Category) => {
    setActiveCategory(cat);
    setActiveSubCategory('All');
    setCurrentPage(1);
  };

  const handleSubCategoryChange = (sub: string) => {
    setActiveSubCategory(sub);
    setCurrentPage(1);
  };

  const loadNews = useCallback(async (cat: Category, subCat: string, sourceIds: string[]) => {
    if (hasAuth === false) return;

    // Generate unique cache key
    const sortedSourceIds = [...sourceIds].sort().join(',');
    const cacheKey = `digest_cache_${cat}_${subCat}_${sortedSourceIds}`;

    // Check Cache
    try {
      const cached = sessionStorage.getItem(cacheKey);
      if (cached) {
        const parsed: CachedData = JSON.parse(cached);
        const now = Date.now();
        if (now - parsed.timestamp < CACHE_TTL) {
          setState({
            items: parsed.items,
            sources: parsed.sources,
            loading: false,
            error: null,
            lastUpdated: parsed.lastUpdatedStr
          });
          setIsFromCache(true);
          return;
        }
      }
    } catch (e) {
      console.warn("Cache retrieval failed", e);
    }

    // If no cache or cache expired, fetch
    setIsFromCache(false);
    setState(prev => ({ ...prev, loading: true, error: null }));

    const currentPresetSources = PRESET_SOURCES_MAP[cat];
    const domains = currentPresetSources
      .filter(s => sourceIds.includes(s.id))
      .map(s => s.domain);

    try {
      const data = await fetchTechNews(cat, subCat, domains);
      const lastUpdatedStr = new Date().toLocaleTimeString([], { hour: '2-digit', minute: '2-digit' });

      setState({
        items: data.items,
        sources: data.sources,
        loading: false,
        error: null,
        lastUpdated: lastUpdatedStr
      });

      // Save to cache
      const cachePayload: CachedData = {
        items: data.items,
        sources: data.sources,
        timestamp: Date.now(),
        lastUpdatedStr: lastUpdatedStr
      };
      sessionStorage.setItem(cacheKey, JSON.stringify(cachePayload));

    } catch (err: any) {
      if (err.message === "AUTH_REQUIRED") {
        setHasAuth(false);
      } else {
        setState(prev => ({ 
          ...prev, 
          loading: false, 
          error: err.message || 'An unexpected error occurred' 
        }));
      }
    }
  }, [hasAuth]);

  const handleOpenAnalysis = async (item: NewsItem) => {
    setSelectedItem(item);
    setIsAnalysisLoading(true);
    setAnalysisData(null);

    try {
      const analysis = await fetchDeepAnalysis(item);
      setAnalysisData(analysis);
    } catch (err: any) {
      if (err.message === "AUTH_REQUIRED") {
        setHasAuth(false);
        setSelectedItem(null);
      }
      console.error(err);
    } finally {
      setIsAnalysisLoading(false);
    }
  };

  const handleCloseAnalysis = () => {
    setSelectedItem(null);
    setAnalysisData(null);
  };

  useEffect(() => {
    if (hasAuth === true) {
      loadNews(activeCategory, activeSubCategory, categorySources[activeCategory]);
    }
  }, [activeCategory, activeSubCategory, categorySources, loadNews, hasAuth]);

  if (hasAuth === false) {
    return (
      <div className="min-h-screen flex items-center justify-center bg-[#0f172a] p-6">
