               </button>
            )}
          </div>
        ) : (
          <>
            <div className="grid grid-cols-1 md:grid-cols-2 lg:grid-cols-3 gap-6">
              {paginatedItems.map((item) => (
                <NewsCard key={item.id} item={item} onAnalyze={handleOpenAnalysis} />
              ))}
            </div>
            {totalPages > 1 && (
              <div className="mt-12 flex items-center justify-center gap-1">
                {Array.from({ length: totalPages }, (_, i) => i + 1).map(page => (
                  <button
                    key={page}
                    onClick={() => setCurrentPage(page)}
                    className={`w-10 h-10 rounded-lg border transition-all text-xs font-bold ${
                      currentPage === page ? 'bg-emerald-600 border-emerald-500 text-white' : 'border-white/10 text-slate-400 hover:bg-white/5'
                    }`}
                  >
                    {page}
                  </button>
                ))}
              </div>
            )}
            <SourceList sources={state.sources} />
          </>
        )}
      </main>

      <footer className="mt-20 py-12 border-t border-white/5 text-center">
        <span className="font-bold text-slate-300">My Daily Digest</span>
        <div className="mt-4 flex gap-4 justify-center text-[10px] text-slate-500 uppercase tracking-widest">
           <button onClick={handleAuthorize} className="hover:text-emerald-400">Reset Authority</button>
           <span>|</span>
           <span>Powered by Gemini 3 Synthesis</span>
        </div>
      </footer>
    </div>
  );
};

export default App;

