    const uniqueSources = Array.from(new Map(sources.map(s => [s.uri, s])).values());

    return {
      marketImpact: analysis.marketImpact || "No analysis available.",
      technicalContext: analysis.technicalContext || "No context available.",
      futureOutlook: analysis.futureOutlook || "No outlook available.",
      sources: uniqueSources
    };
  } catch (error: any) {
    console.error("Gemini API Error (Analysis):", error);
    throw new Error("UNAVAILABLE");
  }
};

import React, { useState, useEffect, useCallback, useMemo } from 'react';
import { fetchTechNews, fetchDeepAnalysis } from './services/geminiService';
