          <div className="py-20 text-center glass rounded-3xl border border-white/5 flex flex-col items-center gap-4">
            <p className="text-slate-400 font-medium">No signals detected from selected sources in this period.</p>
            {!showLowSignal && (
               <button 
                onClick={() => setShowLowSignal(true)}
                className="bg-emerald-600 px-6 py-2 rounded-xl text-xs font-bold text-white hover:bg-emerald-500 transition-all"
