const ITEMS_PER_PAGE = 12;
const CACHE_TTL = 30 * 60 * 1000; // 30 minutes in milliseconds

interface CachedData {
  items: NewsItem[];
  sources: GroundingSource[];
  timestamp: number;
  lastUpdatedStr: string;
}

// Fix: Changed App component from a default export to a named export to resolve the "no default export" error in index.tsx.
