import { GoogleGenAI, Type } from "@google/genai";
import { NewsItem, GroundingSource, AnalysisData } from "../types";

/**
 * Extracts a JSON string from a markdown code block.
 * If no markdown block is found, returns the original text.
 */
function extractJsonFromMarkdown(text: string): string {
  const match = text.match(/```json\n([\s\S]*?)\n```/);
  if (match && match[1]) {
    return match[1];
  }
  // If no markdown block, assume it might be raw JSON directly
  return text;
}

export const fetchTechNews = async (
  category: string = 'Technology', 
  subCategory: string = 'All',
  preferredSources: string[] = []
): Promise<{ items: NewsItem[], sources: GroundingSource[] }> => {
  const ai = new GoogleGenAI({ apiKey: process.env.API_KEY });

  const now = new Date();
  const yesterday = new Date(now.getTime() - (24 * 60 * 60 * 1000));

  const dateStringNow = now.toLocaleDateString('en-US', { year: 'numeric', month: 'long', day: 'numeric', hour: '2-digit', minute: '2-digit' });
  const dateStringYesterday = yesterday.toLocaleDateString('en-US', { year: 'numeric', month: 'long', day: 'numeric', hour: '2-digit', minute: '2-digit' });

  let categoryInstruction = "";
  const subCatText = subCategory !== 'All' ? `Specifically focusing on the sub-topic: ${subCategory}.` : "";

  const sourceText = preferredSources.length > 0 
    ? `CRITICAL: You MUST ONLY return news items that originated from or are reported by these specific domains/outlets: ${preferredSources.join(', ')}. If a story is not covered by these specific brands, exclude it.` 
    : "You may use any reputable global news sources.";

  if (category === 'Politics') {
    categoryInstruction = `Focus on high-stakes political news concerning India, the European Union (EU), and the United States (US). ${subCatText}`;
  } else if (category === 'Geo-politics') {
    categoryInstruction = `Focus on strategic international relations, global diplomacy shifts, and major geopolitical conflicts. ${subCatText}`;
  } else if (category === 'Markets') {
    categoryInstruction = `Focus on major stock market movements, global indices (S&P 500, Nifty, etc.), commodities, and market-moving corporate events. ${subCatText}`;
  } else if (category === 'Finance') {
    categoryInstruction = `Focus on systemic banking shifts, macroeconomic policy changes, corporate earnings of giants, and major fintech developments. ${subCatText}`;
  } else if (category === 'Technology') {
    categoryInstruction = `Focus on industry-shaping AI, strategic startup acquisitions, massive hardware/software breakthroughs, and critical cybersecurity events. ${subCatText}`;
  } else {
    categoryInstruction = `Provide only critical headlines for the selected sector. ${subCatText}`;
  }

  const prompt = `Provide a comprehensive list of EXACTLY 50 unique news items from the LAST 24 HOURS (between ${dateStringYesterday} and ${dateStringNow}). 

  Category Focus: ${category}
  Instruction: ${categoryInstruction}
  Source Constraint: ${sourceText}

  SCORING GUIDELINE (RELEVANCE):
  - Scale: 1 to 10.
  - 10: World-changing/Historical event.
  - 8-9: Major sector-defining news.
  - 5-7: Significant daily news.
  - 1-4: Minor updates or niche news.

  CRITICAL: Since this is a "Daily Digest", MOST actual news stories from the last 24 hours should be scored between 5 and 10. Do not be overly conservative with scores; if it is a real story worth reading today, it is at least a 5.

  MANDATORY: Provide exactly 50 distinct items.

  Structure the response as a JSON array of objects:
  - id: unique string
  - title: clear, impactful headline
  - summary: 1-2 concise sentences
  - category: exactly '${category}'
  - subCategory: the specific sub-topic if applicable
  - source: the primary publisher name (MATCH the names provided in source constraint if applicable, e.g. "TechCrunch", "The Verge")
  - relevance: integer 1-10 (ensure high-quality stories are 5+)`;

  try {
    const response = await ai.models.generateContent({
      model: 'gemini-2.5-flash',
      contents: prompt,
      config: {
        tools: [{ googleSearch: {} }],
      },
    });

    let items: NewsItem[] = [];
    try {
      const rawResponseText = extractJsonFromMarkdown(response.text || "");
      items = JSON.parse(rawResponseText);
    } catch (jsonError) {
      console.error("JSON parsing error in fetchTechNews:", jsonError);
      console.error("Raw model response:", response.text);
      throw new Error("Failed to parse news items from model response.");
    }

    const sources: GroundingSource[] = [];
    const chunks = response.candidates?.[0]?.groundingMetadata?.groundingChunks;

    if (chunks) {
      chunks.forEach((chunk: any) => {
        if (chunk.web && chunk.web.uri && chunk.web.title) {
          sources.push({ title: chunk.web.title, uri: chunk.web.uri });
        }
      });
    }

    const uniqueSources = Array.from(new Map(sources.map(s => [s.uri, s])).values());
    return { items, sources: uniqueSources };
  } catch (error: any) {
    console.error("Gemini API Error (fetchTechNews):", error);
    if (error.message && error.message.includes("Requested entity was not found.")) {
      throw new Error("API key invalid or not found. Please re-select your API key.");
    }
    throw new Error("UNAVAILABLE");
  }
};

export const fetchDeepAnalysis = async (item: NewsItem): Promise<AnalysisData> => {
  const ai = new GoogleGenAI({ apiKey: process.env.API_KEY });

  const prompt = `Perform a strategic deep-dive into: "${item.title}". 
  Context: ${item.summary}

  Analysis required:
  1. Strategic Impact (marketImpact)
  2. Contextual Drivers (technicalContext)
  3. Risk & Future Outlook (futureOutlook)

  CRITICAL: The response MUST be a JSON object with EXACTLY these three top-level keys: "marketImpact", "technicalContext", and "futureOutlook". The values for these keys must be strings.

  Example JSON structure:
  {
    "marketImpact": "Analysis of market impact here...",
    "technicalContext": "Analysis of technical context here...",
    "futureOutlook": "Analysis of future outlook here..."
  }`;

  try {
    const response = await ai.models.generateContent({
      model: 'gemini-2.5-flash',
      contents: prompt,
      config: {
        tools: [{ googleSearch: {} }],
      },
    });

    let analysis: AnalysisData = { marketImpact: "No analysis available.", technicalContext: "No context available.", futureOutlook: "No outlook available.", sources: [] };
    try {
      const rawResponseText = extractJsonFromMarkdown(response.text || "");
      const parsedAnalysis = JSON.parse(rawResponseText);

      // Explicitly map to expected keys, providing fallbacks
      analysis.marketImpact = parsedAnalysis.marketImpact || "No strategic impact analysis available.";
      analysis.technicalContext = parsedAnalysis.technicalContext || "No contextual drivers analysis available.";
      analysis.futureOutlook = parsedAnalysis.futureOutlook || "No risk & future outlook analysis available.";

    } catch (jsonError) {
      console.error("JSON parsing error in fetchDeepAnalysis:", jsonError);
      console.error("Raw model response:", response.text);
      throw new Error("Failed to parse analysis data from model response.");
    }

    const sources: GroundingSource[] = [];
    const chunks = response.candidates?.[0]?.groundingMetadata?.groundingChunks;

    if (chunks) {
      chunks.forEach((chunk: any) => {
        if (chunk.web && chunk.web.uri && chunk.web.title) {
          sources.push({ title: chunk.web.title, uri: chunk.web.uri });
        }
      });
    }

    const uniqueSources = Array.from(new Map(sources.map(s => [s.uri, s])).values());

    return {
      marketImpact: analysis.marketImpact,
      technicalContext: analysis.technicalContext,
      futureOutlook: analysis.futureOutlook,
      sources: uniqueSources
    };
  } catch (error: any) {
    console.error("Gemini API Error (fetchDeepAnalysis):", error);
    if (error.message && error.message.includes("Requested entity was not found.")) {
      throw new Error("API key invalid or not found. Please re-select your API key.");
    }
    throw new Error("UNAVAILABLE");
  }
};

import React, { useState, useEffect } from 'react';

interface LoginGateProps {
  onAuthorized: () => void;
}

const LoginGate: React.FC<LoginGateProps> = ({ onAuthorized }) => {
  const [hasApiKey, setHasApiKey] = useState(false);
  const [loading, setLoading] = useState(true); // Start loading to check API key

  useEffect(() => {
    const checkApiKey = async () => {
      try {
        // Assume window.aistudio is available in this environment
        const keySelected = await window.aistudio.hasSelectedApiKey();
        if (keySelected) {
          setHasApiKey(true);
          onAuthorized(); // Immediately authorize if key is already selected
        } else {
          setHasApiKey(false);
        }
      } catch (e) {
        console.error("Error checking API key:", e);
        setHasApiKey(false); // Assume no key if there's an error checking
      } finally {
        setLoading(false);
      }
    };
    checkApiKey();
  }, [onAuthorized]);

  const handleSelectKey = async () => {
    setLoading(true);
    try {
      await window.aistudio.openSelectKey();
      // As per guidelines, assume success and proceed to app
      onAuthorized();
    } catch (e) {
      console.error("Error opening API key selection dialog:", e);
      // If the dialog itself fails, we reset loading and let user retry
      setLoading(false);
      setHasApiKey(false); // Ensure the UI reflects no key selected
    }
  };

  if (loading) {
    return (
      <div className="min-h-screen flex items-center justify-center bg-[#0f172a] p-6">
        <div className="flex flex-col items-center gap-4">
          <div className="w-12 h-12 border-4 border-emerald-500/20 border-t-emerald-500 rounded-full animate-spin"></div>
          <p className="text-slate-400 font-medium">Checking API Key...</p>
        </div>
      </div>
    );
  }

  return (
    <div className="min-h-screen flex items-center justify-center bg-[#0f172a] p-6 selection:bg-emerald-500/30">
      <div className="max-w-md w-full glass p-10 rounded-[2.5rem] border border-white/10 text-center shadow-2xl relative overflow-hidden">
        {/* Decorative elements */}
        <div className="absolute top-0 left-0 w-full h-1 bg-gradient-to-r from-emerald-500 via-blue-500 to-emerald-500" />
        <div className="absolute -top-24 -right-24 w-48 h-48 bg-emerald-500/10 blur-[80px] rounded-full" />

        <div className="w-20 h-20 bg-emerald-600 rounded-2xl flex items-center justify-center mx-auto mb-8 shadow-lg shadow-emerald-500/20 rotate-3 transition-transform hover:rotate-0 duration-500">
          <span className="text-white font-black text-4xl">D</span>
        </div>

        <h2 className="text-3xl font-bold text-white mb-2 tracking-tight">Daily Digest</h2>
        <p className="text-slate-400 mb-6 leading-relaxed text-sm">
          To access today's market signals, please select an API key. This app requires a paid API key for certain models to function correctly.
        </p>
        <p className="text-slate-500 text-xs mb-8">
          You may be encountering a quota limit or need to use a paid tier API key.
        </p>

          <button
            onClick={handleSelectKey}
            disabled={loading}
            className="w-full bg-emerald-600 hover:bg-emerald-500 disabled:opacity-50 text-white font-bold py-4 rounded-xl transition-all active:scale-[0.98] shadow-lg shadow-emerald-600/20 flex items-center justify-center gap-2 group"
          >
            {loading ? (
              <div className="w-5 h-5 border-2 border-white/20 border-t-white rounded-full animate-spin" />
            ) : (
              <>
                <span>Select API Key</span>
                <svg className="w-4 h-4 group-hover:translate-x-1 transition-transform" fill="none" stroke="currentColor" viewBox="0 0 24 24">
                  <path strokeLinecap="round" strokeLinejoin="round" strokeWidth="2" d="M14 5l7 7m0 0l-7 7m7-7H3" />
                </svg>
              </>
            )}
          </button>


        <div className="mt-8 flex flex-col items-center gap-2">
          <a 
            href="https://ai.google.dev/gemini-api/docs/billing" 
            target="_blank" 
            rel="noopener noreferrer"
            className="text-[10px] font-bold text-slate-500 uppercase tracking-widest hover:text-emerald-400 transition-colors flex items-center gap-1"
          >
            <svg className="w-3 h-3" fill="currentColor" viewBox="0 0 20 20"><path fillRule="evenodd" d="M18 10a8 8 0 11-16 0 8 8 0 0116 0zm-7-4a1 1 0 11-2 0 1 1 0 012 0zM9 9a1 1 0 000 2v3a1 1 0 001 1h1a1 1 0 100-2v-3a1 1 0 00-1-1H9z" clipRule="evenodd"></path></svg>
            Billing & Quota Info
          </a>
          <p className="text-[9px] text-slate-600 uppercase tracking-tighter">Powered by Google Gemini</p>
        </div>
      </div>
    </div>
  );
};

