    // isAuthorized check removed
    const sortedSourceIds = [...sourceIds].sort().join(',');
    const cacheKey = `digest_cache_${cat}_${subCat}_${sortedSourceIds}_${model}`; // Include model in cache key

    try {
      const cached = sessionStorage.getItem(cacheKey);
      if (cached) {
        const parsed: CachedData = JSON.parse(cached);
        const now = Date.now();
        if (now - parsed.timestamp < CACHE_TTL) {
          setState({
            items: parsed.items,
            sources: parsed.sources,
            loading: false,
            error: null,
            lastUpdated: parsed.lastUpdatedStr
          });
          setIsFromCache(true);
          return;
