                  className="px-4 py-2 bg-emerald-600/20 text-emerald-400 rounded-lg disabled:opacity-50 disabled:cursor-not-allowed hover:bg-emerald-600/30 transition-colors"
                >
                  Next
                </button>
              </div>
            )}

            <SourceList sources={state.sources} />
          </>
        )}
      </main>
    </div>
  );
};

