// Simple markdown renderer for blog-like presentation
const renderMarkdown = (markdown: string | undefined) => {
  if (!markdown) return null;

  const lines = markdown.split('\n');
  const elements: JSX.Element[] = [];
  let inList = false;

  lines.forEach((line, index) => {
    // Headings
    if (line.startsWith('## ')) {
      elements.push(<h3 key={index} className="text-lg font-bold text-white mb-2 mt-4">{line.substring(3)}</h3>);
      inList = false;
    } 
    // Bullet points
    else if (line.startsWith('* ')) {
      if (!inList) {
        elements.push(<ul key={`ul-start-${index}`} className="list-disc list-inside text-slate-300 text-base space-y-1 mt-2 mb-2">);
        inList = true;
      }
      // Basic bolding within list items
      const listItemContent = line.substring(2).split('**').map((text, i) => (
        i % 2 === 1 ? <strong key={`bold-${index}-${i}`}>{text}</strong> : text
      ));
      elements.push(<li key={index}>{listItemContent}</li>);
    } 
    // Paragraphs (and basic bolding within paragraphs)
    else if (line.trim() !== '') {
      if (inList) {
        elements.push(<div key={`ul-end-${index}`}></ul></div>); // Close previous list if any
        inList = false;
      }
      const paragraphContent = line.split('**').map((text, i) => (
        i % 2 === 1 ? <strong key={`bold-${index}-${i}`}>{text}</strong> : text
      ));
      elements.push(<p key={index} className="text-slate-300 leading-relaxed text-base mb-2">{paragraphContent}</p>);
    } else if (inList) {
      // Empty line closes a list
      elements.push(<div key={`ul-end-${index}`}></ul></div>);
      inList = false;
    }
  });

  // Ensure any open list is closed
  if (inList) {
    elements.push(<div key={`ul-final-end`}></ul></div>);
  }

  return <>{elements}</>;
};


