                        {new URL(s.uri).hostname}
                      </a>
                    ))}
                  </div>
                </div>
              )}
            </div>
          ) : (
            <div className="text-center py-10 text-rose-400">Strategic synthesis failed for this item.</div>
          )}
        </div>
      </div>
    </div>
  );
};

