const OBFUSCATED_PASSCODE_NUMS = [128, 120, 132, 126, 137, 134, 134, 139];

const getDecryptedPasscode = (): string => {
  return OBFUSCATED_PASSCODE_NUMS.map(charNum =>
    String.fromCharCode(charNum - 23)
  ).join('');
};

