/**
 * Robustly extracts a JSON string from model output.
 * Handles markdown blocks, generic blocks, or raw bracketed strings.
 */
function extractJson(text: string): string | null {
  if (!text) return null;

  // Remove potential markdown code block markers and language identifiers
  // Sometimes the model puts text before/after the block which confuses simple JSON.parse

  // 1. Try markdown block with 'json' tag
  const jsonBlockMatch = text.match(/```json\s*([\s\S]*?)\s*```/);
  if (jsonBlockMatch && jsonBlockMatch[1]) {
    return jsonBlockMatch[1].trim();
  }

  // 2. Try any markdown block
  const genericBlockMatch = text.match(/```\s*([\s\S]*?)\s*```/);
  if (genericBlockMatch && genericBlockMatch[1]) {
    const content = genericBlockMatch[1].trim();
    if (content.startsWith('[') || content.startsWith('{')) {
      return content;
    }
  }

  // 3. Fallback: Find the first [ or { and the last matching ] or }
  // This is useful if the model includes grounding citations or text around the JSON
  const firstBracket = text.search(/[\[\{]/);
  const lastBracket = Math.max(text.lastIndexOf(']'), text.lastIndexOf('}'));

  if (firstBracket !== -1 && lastBracket !== -1 && lastBracket > firstBracket) {
    return text.substring(firstBracket, lastBracket + 1).trim();
  }

  return null;
}

export const fetchTechNews = async (
  category: string = 'Technology', 
  subCategory: string = 'All',
  preferredSources: string[] = [],
  modelName: GeminiModel = 'gemini-3-flash-preview'
): Promise<{ items: NewsItem[], sources: GroundingSource[] }> => {
  const ai = new GoogleGenAI({ apiKey: process.env.API_KEY });

  const now = new Date();
  const yesterday = new Date(now.getTime() - (24 * 60 * 60 * 1000));

  const dateStringNow = now.toLocaleString('en-US', { year: 'numeric', month: 'long', day: 'numeric', hour: '2-digit', minute: '2-digit' });
  const dateStringYesterday = yesterday.toLocaleDateString('en-US', { year: 'numeric', month: 'long', day: 'numeric', hour: '2-digit', minute: '2-digit' });

  let categoryInstruction = "";
  const subCatText = subCategory !== 'All' ? `Specifically focusing on the sub-topic: ${subCategory}.` : "";

  const sourceText = preferredSources.length > 0 
    ? `CRITICAL: You MUST ONLY return news items that originated from or are reported by these specific domains/outlets: ${preferredSources.join(', ')}.` 
    : "Use any reputable global news sources.";

  if (category === 'Politics') {
    categoryInstruction = `Focus on high-stakes political news concerning India, the European Union (EU), and the United States (US). ${subCatText}`;
  } else if (category === 'Geo-politics') {
    categoryInstruction = `Focus on strategic international relations, global diplomacy shifts, and major geopolitical conflicts. ${subCatText}`;
  } else if (category === 'Markets') {
    categoryInstruction = `Focus on major stock market movements, global indices (S&P 500, Nifty, etc.), commodities, and market-moving corporate events. ${subCatText}`;
  } else if (category === 'Finance') {
    categoryInstruction = `Focus on systemic banking shifts, macroeconomic policy changes, corporate earnings of giants, and major fintech developments. ${subCatText}`;
  } else if (category === 'Technology') {
    categoryInstruction = `Focus on industry-shaping AI, strategic startup acquisitions, massive hardware/software breakthroughs, and critical cybersecurity events. ${subCatText}`;
  } else if (category === 'Professional') {
    categoryInstruction = `Focus on specialized professional news for ${subCategory}. Provide tutorials, best practices, and ecosystem updates.`;
  }

  // NOTE: Asking for 50 items with the Google Search tool often causes model refusal or JSON failure 
  // because the search tool's context window gets overwhelmed or the model can't find 50 distinct citations.
  // Lowering the target to 25 items significantly improves reliability.
  const prompt = `You are a real-time news synthesis engine.
  Current Date: ${dateStringNow}.
  Target Window: From ${dateStringYesterday} to ${dateStringNow}.

  TASK: Use Google Search to find the latest updates for: ${category}.
  ${categoryInstruction}
  ${sourceText}

  RULES:
  1. DO NOT mention knowledge cutoffs. You HAVE access to Google Search for real-time data.
  2. Provide exactly 25 unique news items.
  3. Return ONLY a JSON array in a markdown code block.
  4. Each object MUST include: id (unique string), title, summary (concise paragraph), category, subCategory, source (entity name), relevance (1-10), and uri (VALID ARTICLE URL).
  5. If you cannot find exactly 25, provide as many as possible (at least 15).

  Format:
  \`\`\`json
  [
    { "id": "...", "title": "...", "summary": "...", "category": "...", "subCategory": "...", "source": "...", "relevance": 8, "uri": "..." }
  ]
  \`\`\``;

  try {
    const response = await ai.models.generateContent({
      model: modelName,
      contents: prompt,
      config: {
        tools: [{ googleSearch: {} }],
        temperature: 0.1 // Minimal randomness for structural integrity
      },
    });

    const rawResponseText = response.text || "";
    const jsonString = extractJson(rawResponseText);

    if (!jsonString) {
      // Log the refusal message if it wasn't JSON
      console.error("Model Refusal/Error:", rawResponseText);
      throw new Error("UNAVAILABLE: The synthesis engine encountered a temporary limitation. Please try again in a few seconds.");
    }

    try {
      const items = JSON.parse(jsonString);
      if (!Array.isArray(items) || items.length === 0) {
        throw new Error("Invalid structure returned.");
      }

      const sources: GroundingSource[] = [];
      const chunks = response.candidates?.[0]?.groundingMetadata?.groundingChunks;
      if (chunks) {
        chunks.forEach((chunk: any) => {
          if (chunk.web?.uri && chunk.web?.title) {
            sources.push({ title: chunk.web.title, uri: chunk.web.uri });
          }
        });
      }

      return { items, sources: Array.from(new Map(sources.map(s => [s.uri, s])).values()) };
    } catch (parseErr) {
      console.error("JSON Parse Failure:", parseErr, "Text:", jsonString);
      throw new Error("UNAVAILABLE: Data formatting error.");
    }
  } catch (error: any) {
    console.error("fetchTechNews error:", error);
    // Specific check for the "cannot fulfill" refusal to show a better UI message
    if (error.message.includes("knowledge cutoff") || error.message.includes("cannot fulfill")) {
       throw new Error("UNAVAILABLE: The model is currently refusing real-time search. Please try refreshing or switching to a different category.");
    }
    throw new Error(error.message || "Could not synthesize news. Try again.");
  }
};

export const fetchDeepAnalysis = async (
  item: NewsItem,
  modelName: GeminiModel = 'gemini-3-flash-preview'
): Promise<AnalysisData> => {
  const ai = new GoogleGenAI({ apiKey: process.env.API_KEY });

  const prompt = `Perform a strategic deep-dive for: "${item.title}".
  Use Google Search to find context.

  MANDATORY: Return a JSON object with keys: "marketImpact", "technicalContext", and "futureOutlook". 
  Values must be Markdown-formatted strings.
  If search fails, synthesize based on general industry knowledge.`;

  try {
    const response = await ai.models.generateContent({
      model: modelName,
      contents: prompt,
      config: {
        tools: [{ googleSearch: {} }],
        temperature: 0.1
      },
    });

    const jsonString = extractJson(response.text || "");
    if (!jsonString) throw new Error("No structured analysis found.");

    const parsed = JSON.parse(jsonString);

    const sources: GroundingSource[] = [];
    const chunks = response.candidates?.[0]?.groundingMetadata?.groundingChunks;
    if (chunks) {
      chunks.forEach((chunk: any) => {
        if (chunk.web?.uri && chunk.web?.title) {
          sources.push({ title: chunk.web.title, uri: chunk.web.uri });
        }
      });
    }

    return {
      marketImpact: parsed.marketImpact || "Impact analysis unavailable.",
      technicalContext: parsed.technicalContext || "Technical drivers unavailable.",
      futureOutlook: parsed.futureOutlook || "Future outlook unavailable.",
      sources: Array.from(new Map(sources.map(s => [s.uri, s])).values())
    };
  } catch (error: any) {
    console.error("fetchDeepAnalysis error:", error);
    throw new Error("UNAVAILABLE");
  }
};

