import { GoogleGenAI, Type } from "@google/genai";
import { NewsItem, GroundingSource, AnalysisData, GeminiModel } from "../types";

/**
 * Robustly extracts a JSON string from model output.
 * Handles markdown blocks, generic blocks, or raw bracketed strings.
 */
function extractJson(text: string): string | null {
  if (!text) return null;

  // 1. Try markdown block with 'json' tag
  const jsonBlockMatch = text.match(/```json\s*([\s\S]*?)\s*```/);
  if (jsonBlockMatch && jsonBlockMatch[1]) {
    return jsonBlockMatch[1].trim();
  }

  // 2. Try any markdown block
  const genericBlockMatch = text.match(/```\s*([\s\S]*?)\s*```/);
  if (genericBlockMatch && genericBlockMatch[1]) {
    const content = genericBlockMatch[1].trim();
    if (content.startsWith('[') || content.startsWith('{')) {
      return content;
    }
  }

  // 3. Fallback: Find the first [ or { and the last matching ] or }
  const firstBracket = text.search(/[\[\{]/);
  const lastBracket = Math.max(text.lastIndexOf(']'), text.lastIndexOf('}'));

  if (firstBracket !== -1 && lastBracket !== -1 && lastBracket > firstBracket) {
    return text.substring(firstBracket, lastBracket + 1).trim();
  }

  return null;
}

export const fetchTechNews = async (
  category: string, 
  subCategory: string = 'All',
  preferredSources: string[] = [],
  modelName: GeminiModel = 'gemini-3-flash-preview'
): Promise<{ items: NewsItem[], sources: GroundingSource[] }> => {
  const ai = new GoogleGenAI({ apiKey: process.env.API_KEY });

  const now = new Date();
  const yesterday = new Date(now.getTime() - (24 * 60 * 60 * 1000));

  const dateStringNow = now.toLocaleString('en-US', { year: 'numeric', month: 'long', day: 'numeric', hour: '2-digit', minute: '2-digit' });
  const dateStringYesterday = yesterday.toLocaleDateString('en-US', { year: 'numeric', month: 'long', day: 'numeric', hour: '2-digit', minute: '2-digit' });

  let categoryInstruction = "";
  const subCatText = subCategory !== 'All' ? `Specifically focusing on the sub-topic: ${subCategory}.` : "";
  const sourceText = preferredSources.length > 0 
    ? `CRITICAL: You MUST ONLY return news items from these domains: ${preferredSources.join(', ')}.` 
    : "Use any reputable global news sources.";

  if (category === 'Politics') {
    categoryInstruction = `Focus on political news from India, EU, and US. ${subCatText}`;
  } else if (category === 'Geo-politics') {
    categoryInstruction = `Focus on diplomacy and international conflicts. ${subCatText}`;
  } else if (category === 'Markets') {
    categoryInstruction = `Focus on stock market movements, indices, and commodities. ${subCatText}`;
  } else if (category === 'Finance') {
    categoryInstruction = `Focus on economy, banking, and fintech. ${subCatText}`;
  } else if (category === 'Technology') {
    categoryInstruction = `Focus on AI, hardware, software, and cybersecurity. ${subCatText}`;
  } else if (category === 'Professional') {
    categoryInstruction = `Focus on professional updates for: ${subCategory}.`;
  }

  // Refined prompt to handle "cannot fulfill" hallucinations
  const prompt = `YOU ARE A REAL-TIME SEARCH ENGINE.
  USE THE GOOGLE SEARCH TOOL TO SCAN THE WEB RIGHT NOW.
  CURRENT TIME: ${dateStringNow}
  WINDOW: FROM ${dateStringYesterday} TO ${dateStringNow}

  TASK: Synthesize exactly 25 major headlines for the category: ${category}.
  ${categoryInstruction}
  ${sourceText}

  MANDATORY GUIDELINES:
  1. IGNORE internal knowledge cutoff dates. Rely SOLELY on results from the Google Search tool for recent events.
  2. Provide exactly 25 items if possible (minimum 15).
  3. Respond ONLY with a valid JSON array inside a markdown block.
  4. Use keys: "id" (string), "title", "summary" (detailed paragraph), "category", "subCategory", "source", "relevance" (1-10), "uri" (valid URL).

  JSON FORMAT:
  \`\`\`json
  [
    { "id": "...", "title": "...", "summary": "...", "category": "...", "subCategory": "...", "source": "...", "relevance": 8, "uri": "..." }
  ]
  \`\`\``;

  try {
    const response = await ai.models.generateContent({
      model: modelName,
      contents: prompt,
      config: {
        tools: [{ googleSearch: {} }],
        temperature: 0.1
      },
    });

    const rawResponseText = response.text || "";
    const jsonString = extractJson(rawResponseText);

    if (!jsonString) {
      console.error("Refusal/Non-JSON response:", rawResponseText);
      throw new Error("UNAVAILABLE: The model is currently prioritizing safety filters over news synthesis. Please try again or switch categories.");
    }

    try {
      const items = JSON.parse(jsonString);
      if (!Array.isArray(items) || items.length === 0) {
        throw new Error("Invalid structure.");
      }

      const sources: GroundingSource[] = [];
      const chunks = response.candidates?.[0]?.groundingMetadata?.groundingChunks;
      if (chunks) {
        chunks.forEach((chunk: any) => {
          if (chunk.web?.uri && chunk.web?.title) {
            sources.push({ title: chunk.web.title, uri: chunk.web.uri });
          }
        });
      }

      return { items, sources: Array.from(new Map(sources.map(s => [s.uri, s])).values()) };
    } catch (parseErr) {
      console.error("JSON Parsing Error:", parseErr, "Content:", jsonString);
      throw new Error("UNAVAILABLE: Error parsing synthesized data.");
    }
  } catch (error: any) {
    console.error("fetchTechNews global error:", error);
    if (error.message.includes("cutoff") || error.message.includes("fulfill")) {
       throw new Error("UNAVAILABLE: The synthesis engine is temporarily blocked by its internal safety guidelines for real-time data. Please refresh.");
    }
    throw new Error(error.message || "Failed to load news digest.");
  }
};

export const fetchDeepAnalysis = async (
  item: NewsItem,
  modelName: GeminiModel = 'gemini-3-flash-preview'
): Promise<AnalysisData> => {
  const ai = new GoogleGenAI({ apiKey: process.env.API_KEY });

  const prompt = `Deep strategic analysis for: "${item.title}".
  Use Google Search for context.

  MANDATORY: JSON response with "marketImpact", "technicalContext", and "futureOutlook". Use Markdown for text values.`;

  try {
    const response = await ai.models.generateContent({
      model: modelName,
      contents: prompt,
      config: {
        tools: [{ googleSearch: {} }],
        temperature: 0.1
      },
    });

    const jsonString = extractJson(response.text || "");
    if (!jsonString) throw new Error("Analysis synthesis failed.");

    const parsed = JSON.parse(jsonString);

    const sources: GroundingSource[] = [];
    const chunks = response.candidates?.[0]?.groundingMetadata?.groundingChunks;
    if (chunks) {
      chunks.forEach((chunk: any) => {
        if (chunk.web?.uri && chunk.web?.title) {
          sources.push({ title: chunk.web.title, uri: chunk.web.uri });
        }
      });
    }

    return {
      marketImpact: parsed.marketImpact || "Market impact analysis unavailable.",
      technicalContext: parsed.technicalContext || "Technical context unavailable.",
      futureOutlook: parsed.futureOutlook || "Future outlook unavailable.",
      sources: Array.from(new Map(sources.map(s => [s.uri, s])).values())
    };
  } catch (error: any) {
    console.error("fetchDeepAnalysis error:", error);
    throw new Error("UNAVAILABLE");
  }
};

